insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَائِشَةَ رضي الله عنها قَالَتْ: خسفت الشَّمْسُ في عهد رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، فَأَطَالَ الْقِيَامَ جِدًّا، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ جِدًّا، ثُمَّ رَفَعَ رَأْسَهُ فَأَطَالَ الْقِيَامَ جِدًّا، وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ جِدًّا، وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ سَجَدَ ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ رَفَعَ رَأْسَهُ فَقَامَ، فَأَطَالَ الْقِيَامَ وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ سَجَدَ ثُمَّ انْصَرَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَدْ تَجَلَّتِ الشَّمْسُ، فَخَطَبَ النَّاسَ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "إِنَّ الشَّمْسَ وَالْقَمَرَ مِنْ آيَاتِ اللَّهِ، وَإِنَّهُمَا لَا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمُوهُمَا فَكَبِّرُوا، وَادْعُوا اللهَ وَصَلُّوا وَتَصَدَّقُوا، يَا أُمَّةَ مُحَمَّدٍ، إِنْ مِنْ أَحَدٍ أَغْيَرَ مِنَ اللهِ أَنْ يَزْنِيَ عَبْدُهُ أَوْ تَزْنِيَ أَمَتُهُ. يَا أُمَّةَ مُحَمَّدٍ، وَاللهِ لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَبَكَيْتُمْ كَثِيرًا وَلَضَحِكْتُمْ قَلِيلًا، أَلَا هَلْ بَلَّغْتُ". (ق,ن)', 'ആഇശ(റ): പ്രവാചക(സ)ന്റെ കാലത്ത് സൂര്യ ഗ്രഹണം ഉണ്ടായി. അപ്പോൾ അവിടുന്ന് നിസ്കാരത്തിനായി നിന്നു. നിസ്കാരത്തിൽ നിർത്തം കൂടുതൽ ദീർഘമാക്കി. പിന്നെ റുകൂഅ് ചെയ്തു. റുകൂഉും കൂടുതൽ സമയം നിർവ്വഹിച്ചു. ശേഷം റുകൂഇൽ നിന്നും തലയുയർത്തി. വളരെ നേരം നിന്നു. എന്നാൽ അത് ആദ്യത്തെ നിർത്തത്തെക്കാൾ ദൈർഘ്യം കുറവായിരുന്നു. വീണ്ടും പ്രവാചകൻ(സ) റുകൂഅ് ചെയ്തപ്പോൾ അതിന്റെ സമയം ദീർഘിപ്പിച്ചു. എങ്കിലും അത് ആദ്യത്തേതിനേക്കാൾ ദൈർഘ്യം കുറവായിരുന്നു. ശേഷം തലയുയർത്തി നിൽക്കുകയും നിർത്തത്തെ ദീർഘിപ്പിക്കുകയും ചെയ്തു. പക്ഷേ അതിന് ആദ്യത്തെ നിർത്തത്തിന്റെ ദൈർഘ്യമുണ്ടായിരുന്നില്ല. ശേഷം റുകൂഅ് ചെയ്യുകയും അതിനെ ദീർഘിപ്പിക്കുകയും ചെയ്തു. പക്ഷേ അത് ആദ്യ റുകൂഇന്റെയത്ര ദൈർഘ്യമുണ്ടായിരുന്നില്ല. പിന്നീട് സുജൂദ് ചെയ്തു. ശേഷം പ്രവാചകൻ(സ) നിന്നു. അപ്പോഴും പ്രവാചകൻ(സ) ദീർഘനേരം നിന്നു. എങ്കിലും അത് ആദ്യത്തെ റക്അത്തിലെ നിർത്തത്തെക്കാൾ ദൈർഘ്യം കുറവായിരുന്നു. പിന്നീട് റുകൂഅ് ചെയ്തു. അപ്പോഴും അത് ദീർഘിപ്പിച്ചു. എങ്കിലും അത് ആദ്യത്തെ റുകൂഇനേക്കാൾ ദൈർഘ്യം കുറവായിരുന്നു. പിന്നീട് സുജൂദ് ചെയ്തു. പിന്നെ പ്രവാചകൻ(സ) നിസ്കാരത്തിൽ നിന്നും വിരമിച്ചു. അപ്പോൾ സൂര്യൻ പ്രകടമായിട്ടുണ്ടായിരുന്നു. തുടർന്ന് ജനങ്ങൾക്ക് ഖുതുബ നിർവ്വഹിച്ചു. അല്ലാഹുവിനെ സ്തുതിക്കുകയും വാഴ്ത്തുകയും ചെയ്തു. ശേഷം പറഞ്ഞു: "നിശ്ചയം, സൂര്യനും ചന്ദ്രനും അല്ലാഹുവിന്റെ ദൃഷ്ടാന്തങ്ങളിൽ പെട്ടവയാണ്. അവ രണ്ടിനും ആരുടെയും മരണം കാരണമായോ, ജനനം കാരണമായോ ഗ്രഹണം ബാധിക്കുകയില്ല. മുഹമ്മദിന്റെ സമൂഹമേ,!! അവ രണ്ടിനെയും (സൂര്യ ചന്ദ്ര ഗ്രഹണത്തെ) നിങ്ങൾ കണ്ടാൽ തക്ബീർ ചൊല്ലുകയും അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുകയും നിസ്കരിക്കുകയും ദാനധർമ്മങ്ങൾ നൽകുകയും ചെയ്യുവിൻ, മുഹമ്മദിന്റെ സമൂഹമേ, തന്റെ ദാസനോ ദാസിയോ വ്യഭിചരിക്കുന്നതിൽ അല്ലാഹുവിനെക്കാൾ രോഷമുള്ളവൻ ഇല്ല. മുഹമ്മദിന്റെ സമൂഹമേ, അല്ലാഹുവാണെ സത്യം, ഞാൻ അറിയുന്ന കാര്യങ്ങൾ നിങ്ങൾ അറിഞ്ഞിരുന്നെങ്കിൽ! നിങ്ങൾ ധാരാളം കരയുകയും അൽപം മാത്രം ചിരിക്കുകയും ചെയ്യുമായിരുന്നു. അറിയുക! ഞാൻ (നിങ്ങൾക്ക് ഈ സത്യസന്ദേശം) എത്തിച്ചു തന്നില്ലയോ?" (ബു,മു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حين كَسَفَتِ الشَّمْسُ ثَمَانَ رَكَعَاتٍ فِي أَرْبَعِ سَجَدَاتٍ. (م,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): സൂര്യ ഗ്രഹണമുണ്ടായപ്പോൾ നാലു സുജൂദുകളിലായി എട്ടു റക്അത്ത് പ്രവാചകൻ(സ) നിസ്കരിച്ചു. (മു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 635, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَائِشَةَ رَضِي اللَّهُ عَنْهَا، أَنَّهَا قَالَتْ: كُسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ بِالنَّاسِ قِيَامًا شَدِيدًا: يَقُومُ بِالنَّاسِ، ثُمَّ يَرْكَعُ، ثُمَّ يَقُومُ، ثُمَّ يَرْكَعُ، ثُمَّ يَقُومُ، ثُمَّ يَرْكَعُ، فَرَكَعَ رَكْعَتَيْنِ: فِي كُلِّ رَكْعَةٍ ثَلَاثَ رَكَعَاتٍ، يَرْكَعُ الثَّالِثَةَ ثُمَّ سَجَدَ، حَتَّى إِنَّ رِجَالًا يَوْمَئِذٍ يُغْشَى عَلَيْهِمْ مِمَّا قَامَ بِهِمْ، يَقُولُ إِذَا رَكَعَ: "اللَّهُ أَكْبَرُ". وَإِذَا رَفَعَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ". حَتَّى تَجَلَّتِ الشَّمْسُ، ثُمَّ قَالَ: "إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، وَلَكِنَّهُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ عَزَّوَجَلَّ يُخَوِّفُ بِهِمَا عِبَادَهُ، فَإِذَا كَسَفَا فَافْزَعُوا إِلَى الصَّلَاةِ. (م,د,ن,جه)', 'ആഇശ(റ): പ്രവാചക(സ)ന്റെ കാലത്ത് സൂര്യ ഗ്രഹണം ഉണ്ടായപ്പോൾ നബി(സ) വളരെ കൂടുതൽ നേരം ജനങ്ങൾക്ക് ഇമാമായി നിന്ന് നിസ്കരിച്ചു. ശേഷം റുകൂഅ് ചെയ്യും, പിന്നീട് നിൽക്കും, വീണ്ടും റുകൂഅ് ചെയ്യും, വീണ്ടും നിൽക്കും, വീണ്ടും റുകൂഅ് ചെയ്യും, ഈ രീതിയിൽ പ്രവാചകൻ(സ) രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. ഓരോ റക്അത്തിലും മൂന്ന് റുകൂഉകൾ വീതമുണ്ട്. അവിടുന്ന് മൂന്നാമത്തെ റുകൂഅ് ചെയ്തിട്ട് സുജൂദ് ചെയ്യും. എത്രത്തോളമെന്നാൽ, പ്രസ്തുത നിസ്കാരത്തിലെ വളരെ നീണ്ട നിർത്തം കാരണം (പ്രവാചകനെ പിൻതുടർന്ന് നിസ്കരിച്ചിരുന്ന) ചില പുരുഷന്മാർ ആ ദിവസം ബോധ രഹിതരായി. പ്രവാചകൻ(സ) റുകൂഅ് ചെയ്യുമ്പോൾ ''അല്ലാഹു അക്ബർ'' എന്നും, റുകൂഇൽ നിന്നുയർന്നാൽ ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' എന്നും പറഞ്ഞിരുന്നു. സൂര്യൻ പൂർണ്ണമായി വെളിവാകുന്നത് വരെ നിസ്കാരം തുടരുമായിരുന്നു. തുടർന്ന് പ്രവാചകൻ(സ) പറഞ്ഞു: "നിശ്ചയം, സൂര്യന്നും ചന്ദ്രന്നും ആരുടെയും മരണവും ജനനവും കാരണമായി ഗ്രഹണം ബാധിക്കുകയില്ല. എന്നാൽ അവ രണ്ടും അല്ലാഹുവിന്റെ (അനേക) ദൃഷ്ടാന്തങ്ങളിൽ പെട്ട രണ്ട് ദൃഷ്ടാന്തങ്ങളാണ്. അവ മുഖേന അല്ലാഹു തന്റെ ദാസന്മാരെ ഭയപ്പെടുത്തുന്നു. അവ രണ്ടിനും ഗ്രഹണം ബാധിച്ചാൽ നിങ്ങൾ നിസ്കാരത്തിൽ അഭയം തേടുക." (മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 636, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ صَلَّى فِي كُسُوف، فَقَرَأَ ثُمَّ رَكَعَ، ثُمَّ قَرَأَ، ثُمَّ رَكَعَ، ثُمَّ قَرَأَ، ثُمَّ رَكَعَ ثَلَاثَ مَرَّاتٍ، ثُمَّ سَجَدَ سَجْدَتَيْنِ. وَالْأُخْرَى مِثْلُهَا. حَسَنٌ صَحِيحٌ. (م,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): സൂര്യ ഗ്രഹണ വേളയിൽ പ്രവാചകൻ(സ) നിസ്കരിച്ചു. അങ്ങനെ ഖുർആൻ ഓതുകയും, പിന്നീട് റുകൂഅ് ചെയ്യുകയും, വീണ്ടും ഖുർആൻ ഓതുകയും, വീണ്ടും റുകൂഅ് ചെയ്യുകയും ചെയ്തു. തുടർന്നും ഖുർആൻ ഓതുകയും, റുകൂഅ് ചെയ്യുകയും ചെയ്തു. അങ്ങനെ മൂന്ന് പ്രാവശ്യം ചെയ്തു. അനന്തരം രണ്ട് സുജൂദ് ചെയ്തു. അടുത്ത റക്അത്തും ആദ്യത്തെ പോലെ നിസ്കരിച്ചു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (മു,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 636, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: انْكَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَخَرَجَ فَزِعًا يَجُرُّ ثَوْبَهُ حَتَّى أَتَى الْمَسْجِدَ، فَلَمْ يَزَلْ يُصَلِّي حَتَّى انْجَلَتْ، ثُمَّ قَالَ: "إِنَّ أُنَاسًا يَزْعُمُونَ أَنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْكَسِفَانِ إِلَّا لِمَوْتِ عَظِيمٍ مِنَ الْعُظَمَاءِ، وَلَيْسَ كَذَلِكَ، إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا تَجَلَّى اللَّهُ لِشَيْءٍ مِنْ خَلْقِهِ خَشَعَ لَهُ". (د,ن,جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): പ്രവാചക(സ)ന്റെ കാലത്ത് സൂര്യ ഗ്രഹണം ഉണ്ടായപ്പോൾ നബി(സ) ഭയ വിഹ്വലനായി തന്റെ വസ്ത്രങ്ങൾ വലിച്ചിഴച്ചുകൊണ്ട് പള്ളിയിലേക്ക് വന്നു. സൂര്യൻ പൂർണ്ണമായി വെളിവാകുന്നത് വരെ നിസ്കാരത്തിൽ മുഴുകിയ ശേഷം പ്രവാചകൻ(സ) പറഞ്ഞു: "ഏതെങ്കിലും മഹാ വ്യക്തിയുടെ മരണ കാരണമായിട്ടല്ലാതെ സൂര്യനും ചന്ദ്രനും ഗ്രഹണം ബാധിക്കുകയില്ലെന്ന് ചിലർ വാദിക്കുന്നുണ്ടെങ്കിലും യാഥാർത്ഥ്യം അപ്രകാരമല്ല. നിശ്ചയം, ജനങ്ങളിൽ നിന്ന് ആരുടെയും മരണം കാരണമായി സൂര്യനും ചന്ദ്രനും ഗ്രഹണം ബാധിക്കുകയില്ല. അല്ലാഹു ഏതെങ്കിലും ഒരു സൃഷ്ടിക്ക് പ്രകടമായാൽ ആ സൃഷ്ടി അല്ലാഹുവിനെ ഭയപ്പെടുന്നു." (ദ,ന,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 636, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْكُسُوفِ، فَلَا نَسْمَعْ لَهُ صَوْتًا. (د,ت,ن,جه)', 'സമുറതു ബ്നു ജുൻദുബ്(റ): സൂര്യ ഗ്രഹണ സമയത്ത് നബി(സ) ഞങ്ങൾക്ക് ഇമാമായി നിന്ന് നിസ്കരിച്ചു. (ഖുർആൻ പാരായണത്തിന്റെ) ശബ്ദം തിരുമേനി(സ)യിൽനിന്നും ഞങ്ങൾ കേട്ടിരുന്നില്ല. (ദ,തു,ന,ജ)', 'سَمُرَةَ بْنِ جُنْدَبٍ', 'സമുറതു ബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْكُسُوفِ: فَقَامَ فَأَطَالَ الْقِيَامَ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ رَفَعَ فَقَامَ فَأَطَالَ الْقِيَامَ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ، ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ، ثُمَّ رَفَعَ فَقَامَ فَأَطَالَ الْقِيَامَ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ رَفَعَ، فَقَامَ فَأَطَالَ الْقِيَامَ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ رَفَعَ ثُمَّ سَجَدَ، فَأَطَالَ السُّجُودَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ، فَأَطَالَ السُّجُودَ ثُمَّ انْصَرَفَ فَقَالَ: "لَقَدْ دَنَتْ مِنِّي الْجَنَّةُ حَتَّى لَوِ اجْتَرَأْتُ عَلَيْهَا لَجِئْتُكُمْ بِقِطَافٍ مِنْ قِطَافِهَا، وَدَنَتْ مِنِّي النَّارُ حَتَّى قُلْتُ: أَيْ رَبِّ، وَأَنَا فِيهِمْ". قَالَ نَافِعٌ: حَسِبْتُ أَنَّهُ قَالَ: "وَرَأَيْتُ امْرَأَةً تَخْدِشُهَا هِرَّةٌ لَهَا، فَقُلْتُ: مَا شَأْنُ هَذِهِ؟ قَالُوا: حَبَسَتْهَا حَتَّى مَاتَتْ جُوعًا، لَا هِيَ أَطْعَمَتْهَا، وَلَا هِيَ أَرْسَلَتْهَا تَأْكُلُ مِنْ خِشَاشِ الْأَرْضِ". (جه)', 'അസ്മാഅ് ബിൻത് അബീ ബക്റ(റ): സൂര്യ ഗ്രഹണ സമയത്ത് നബി(സ) നിസ്കരിച്ചു. (നിസ്കാരത്തിൽ) തിരുമേനി(സ) നിൽക്കുകയും നിറുത്തത്തെ ദീർഘിപ്പിക്കുകയും, പിന്നീട് റുകൂഅ് ചെയ്യുകയും, റുകൂഅ് ദീർഘിപ്പിക്കുകയും, ശേഷം നിൽക്കുകയും, ആ നിൽപ് ദീർഘിപ്പിക്കുകയും ചെയ്തു. വീണ്ടും റുകൂഅ് ചെയ്യുകയും റുകൂഅ് ദീർഘിപ്പിക്കുകയും, ശേഷം ഉയരുകയും ചെയ്തു. പിന്നീട് സുജൂദ് ചെയ്യുകയും സുജൂദിനെ നീട്ടുകയും ചെയ്തു. ശേഷം സുജൂദിൽ നിന്നുയർന്ന് വീണ്ടും ദീർഘമായ സുജൂദ് ചെയ്യുകയും ചെയ്തു. പിന്നെ ഉയർന്ന് നിന്ന് നിറുത്തത്തെ ദീർഘിപ്പിച്ചു. തുടർന്ന് റുകൂഅ് ചെയ്യുകയും, റുകൂഅ് ദീർഘിപ്പിക്കുകയും ചെയ്തു. ശേഷം ഉയർന്ന് നിൽക്കുകയും നിറുത്തത്തെ ദീർഘിപ്പിക്കുകയും ചെയ്തു. പിന്നീട് റുകൂഅ് ചെയ്യുകയും, റുകൂഅ് ദീർഘിപ്പിച്ച ശേഷം ഉയരുകയും ചെയ്തു. ശേഷം സുജൂദ് ചെയ്യുകയും സുജൂദിനെ നീട്ടുകയും ചെയ്തു. പിന്നെ തിരുമേനി(സ) ഉയർന്നു, വീണ്ടും ദീർഘമായ സുജൂദ് ചെയ്ത ശേഷം നബി(സ) നിസ്കാരത്തിൽ നിന്ന് വിരമിക്കുകയും (ഇങ്ങനെ) പറയുകയും ചെയ്തു: "നിശ്ചയം, സ്വർഗ്ഗം എന്നോട് അടുത്തു. ഞാൻ ധൈര്യപ്പെട്ടിരുന്നുവെങ്കിൽ സ്വർഗ്ഗത്തിലെ (പഴ) കുലകളിൽ നിന്ന് ഒരു കുല ഞാൻ നിങ്ങൾക്ക് കൊണ്ടു വരുമായിരുന്നു. നരകവും എന്നോട് അടുത്തു. ഞാൻ പറഞ്ഞു പോയി: എന്റെ നാഥാ,... അവരിൽ ഞാനും ഉണ്ടോ?" (നിവേദകൻ) നാഫിഅ്(റ) പറയുന്നു: നബി(സ) ഇപ്രകാരം പറഞ്ഞതായി ഞാൻ കരുതുന്നു. "(നരകത്തിൽ) ഒരു സ്ത്രീയേയും ഞാൻ കണ്ടു. അവളുടെ പൂച്ച അവളെ മാന്തിക്കീറിക്കൊണ്ടിരിക്കുന്നു. ഞാൻ ചോദിച്ചു: എന്താണിവളുടെ അവസ്ഥ? അവർ (മലക്കുകൾ) പറഞ്ഞു: വിശന്നു ചാകുന്നതു വരെ പൂച്ചയെ അവൾ തടഞ്ഞുവെച്ചു. അവൾ അതിന് ആഹാരം കൊടുത്തില്ല. ഭൂമിയിലുള്ള ഉണങ്ങിയ പുല്ലുകൾ തിന്നാൻ പോലും അവൾ അതിനെ അഴിച്ചുവിടുകയും ചെയ്തില്ല." (ജ)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻത് അബീ ബക്റ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: خَسَفَتِ الشَّمْسُ فِي حَيَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ فَكَبَّرَ وَصَفَّ النَّاسُ وَرَاءَهُ، فَاقْتَرَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِرَاءَةً طَوِيلَةً، ثُمَّ كَبَّرَ فَرَكَعَ رُكُوعًا طَوِيلًا، ثُمَّ رَفَعَ رَأْسَهُ، فَقَالَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ". ثُمَّ قَامَ فَاقْتَرَأَ قِرَاءَةً طَوِيلَةً هِيَ أَدْنَى مِنَ الْقِرَاءَةِ الْأُولَى، ثُمَّ كَبَّرَ فَرَكَعَ رُكُوعًا طَوِيلًا، هُوَ أَدْنَى مِنَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ قَالَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ". ثُمَّ سَجَدَ، ثُمَّ فَعَلَ فِي الرَّكْعَةِ الْأُخْرَى مِثْلَ ذَلِكَ، فَاسْتَكْمَلَ أَرْبَعَ رَكَعَاتٍ وَأَرْبَعَ سَجَدَاتٍ، وَانْجَلَتِ الشَّمْسُ قَبْلَ أَنْ يَنْصَرِفَ، ثُمَّ قَامَ فَخَطَبَ النَّاسَ، فَأَثْنَى عَلَى اللَّهِ عَزَّ وَجَلَّ بِمَا هُوَ أَهْلُهُ، ثُمَّ قَالَ: "إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ تَعَالَى، لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمُوهُمَا فَصَلُّوا حَتَّى يُفَرَّجَ عَنْكُمْ". وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "رَأَيْتُ فِي مَقَامِي هَذَا كُلَّ شَيْءٍ وُعِدْتُمْ، لَقَدْ رَأَيْتُمُونِي أَرَدْتُ أَنْ آخُذَ قِطْفًا مِنَ الْجَنَّةِ حِينَ رَأَيْتُمُونِي جَعَلْتُ أَتَقَدَّمُ، وَلَقَدْ رَأَيْتُ جَهَنَّمَ يَحْطِمُ بَعْضُهَا بَعْضًا حِينَ رَأَيْتُمُونِي تَأَخَّرْتُ، وَرَأَيْتُ فِيهَا ابْنَ لُحَيٍّ وَهُوَ الَّذِي سَيَّبَ السَّوَائِبَ". (ق,د,ت,ن,جه)', 'ആഇശ(റ): പ്രവാചക(സ)ന്റെ കാലത്ത് സൂര്യ ഗ്രഹണം ഉണ്ടായപ്പോൾഅവിടുന്ന് നിൽക്കുകയും തക്ബീർ ചൊല്ലുകയും ചെയ്തു. പ്രവാചക(സ)ന്റെ പിന്നിൽ ജനങ്ങളും അണിയായി നിന്നു. നബി(സ) ദീർഘമായി പാരായണം ചെയ്തു. പിന്നെ തക്ബീർ ചൊല്ലുകയും, ശേഷം ദീർഘമായി റുകൂഅ് ചെയ്യുകയും ചെയ്തു. പിന്നീട് തല ഉയർത്തി, ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു, റബ്ബനാ ലകൽ ഹംദു'' എന്നു പറഞ്ഞ് പിന്നെയും നിൽക്കുകയും ദീർഘമായി പാരായണം ചെയ്യുകയും ചെയ്തു. അത് ആദ്യത്തെ പാരായണത്തേക്കാൾ ദൈർഘ്യം കുറവായിരുന്നു. തുടർന്ന് തക്ബീർ ചൊല്ലി, ദീർഘമായി റുകൂഅ് ചെയ്തു. അത് ആദ്യത്തെതിനേക്കാൾ ദൈർഘ്യം കുറവായിരുന്നു. ശേഷം ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു, റബ്ബനാ ലകൽ ഹംദു'' എന്നു പറഞ്ഞു. ശേഷം സുജൂദ് ചെയ്തു. പിന്നെ മേൽ പ്രകാരം അടുത്ത റക്അത്തും നിസ്കരിച്ചു. അങ്ങനെ നാലു സുജൂദുകളും നാലു റുകൂഉകളും പൂർത്തിയാക്കി. പ്രവാചകൻ(സ) നിസ്കാരത്തിൽ നിന്നും വിരമിക്കുന്നതിനു മുൻപ് സൂര്യൻ പൂർണ്ണമായി പ്രകാശിക്കുകയും ചെയ്തു. പിന്നെ പ്രവാചകൻ(സ) ജനങ്ങളെ അഭിസംബോധന ചെയ്യുവാനായി എഴുന്നേറ്റ് നിന്നു. അല്ലാഹുവിനെ അവനർഹിക്കുന്ന വചനങ്ങളിലൂടെ സ്തുതിച്ചു. തുടർന്ന് പറഞ്ഞു: "നിശ്ചയം, സൂര്യനും ചന്ദ്രനും അല്ലാഹുവിന്റെ (അനേക) ദൃഷ്ടാന്തങ്ങളിൽ പെട്ട രണ്ട് ദൃഷ്ടാന്തങ്ങളാണ്. ആരുടെയും മരണവും ജനനവും കാരണമായി അവക്ക് ഗ്രഹണം ബാധിക്കുകയില്ല. അവ രണ്ടിനും ഗ്രഹണം ബാധിച്ചതായി നിങ്ങൾ ദർശിച്ചാൽ ഗ്രഹണം പൂർണ്ണമായി ഒഴിവാകുന്നതു വരെ നിങ്ങൾ നിസ്കരിക്കുവിൻ!" പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് വാഗ്ദാനം ചെയ്യപ്പെട്ടിരിക്കുന്നതെല്ലാം എന്റെ ഈ സ്ഥാനത്ത് ഞാൻ കണ്ടിരിക്കുന്നു. ഞാൻ മുന്നോട്ട് നീങ്ങുന്നതായി നിങ്ങൾ എന്നെ കണ്ടപ്പോൾ സ്വർഗ്ഗത്തിൽ നിന്ന് ഒരു കുല പഴം പറിച്ചെടുക്കുവാനുള്ള വിചാരത്തോടെ ഞാൻ മുന്നോട്ട് നീങ്ങുകയായിരുന്നു. ഞാൻ പിന്നോട്ട് മാറുന്നതായി നിങ്ങൾ എന്നെ കണ്ടപ്പോൾ പരസ്പരം പൊട്ടിക്കാൻ ശ്രമിക്കുന്ന നിലയിൽ നരകത്തെ ഞാൻ കാണുകയായിരുന്നു. ''ഇബ്നുലുഹയ്യ്'' എന്നയാളെ നരകത്തിൽ ഞാൻ കണ്ടു. അവനാണ് സർവ്വ സ്വതന്ത്രമായി ചുറ്റി നടക്കാൻ (വിഗ്രഹങ്ങൾക്ക്) മൃഗങ്ങളെ നേർച്ചയാക്കിയവൻ." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 637, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: انْكَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الصَّلَاةِ، وَقَامَ الَّذِينَ مَعَهُ فَقَامَ قِيَامًا فَأَطَالَ الْقِيَامَ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ رَفَعَ رَأْسَهُ وَسَجَدَ فَأَطَالَ السُّجُودَ، ثُمَّ رَفَعَ رَأْسَهُ وَجَلَسَ فَأَطَالَ الْجُلُوسَ، ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ، ثُمَّ رَفَعَ رَأْسَهُ وَقَامَ، فَصَنَعَ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ مَا صَنَعَ فِي الرَّكْعَةِ الْأُولَى: مِنَ الْقِيَامِ، وَالرُّكُوعِ، وَالسُّجُودِ، وَالْجُلُوسِ، فَجَعَلَ يَنْفُخُ فِي آخِرِ سُجُودِهِ مِنَ الرَّكْعَةِ الثَّانِيَةِ، وَيَبْكِي وَيَقُولُ: "لَمْ تَعِدْنِي هَذَا وَأَنَا فِيهِمْ، لَمْ تَعِدْنِي هَذَا وَنَحْنُ نَسْتَغْفِرُكَ". ثُمَّ رَفَعَ رَأْسَهُ وَانْجَلَتِ الشَّمْسُ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخَطَبَ النَّاسَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ عَزَّ وَجَلَّ، فَإِذَا رَأَيْتُمْ كُسُوفَ أَحَدِهِمَا فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ عَزَّ وَجَلَّ. وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَقَدْ أُدْنِيَتِ الْجَنَّةُ مِنِّي حَتَّى لَوْ بَسَطْتُ يَدِي لَتَعَاطَيْتُ مِنْ قُطُوفِهَا، وَلَقَدْ أُدْنِيَتِ النَّارُ مِنِّي، حَتَّى لَقَدْ جَعَلْتُ أَتَّقِيهَا خَشْيَةَ أَنْ تَغْشَاكُمْ، حَتَّى رَأَيْتُ فِيهَا امْرَأَةً مِنْ حِمْيَرَ تُعَذَّبُ فِي هِرَّةٍ رَبَطَتْهَا، فَلَمْ تَدَعْهَا تَأْكُلُ مِنْ خَشَاشِ الْأَرْضِ، فَلَا هِيَ أَطْعَمَتْهَا وَلَا هِيَ سَقَتْهَا حَتَّى مَاتَتْ، فَلَقَدْ رَأَيْتُهَا تَنْهَشُهَا إِذَا أَقْبَلَتْ، وَإِذَا وَلَّتْ تَنْهَشُ أَلْيَتَهَا. وَحَتَّى رَأَيْتُ فِيهَا صَاحِبَ السبتيتين أَخَا بَنِي الدَّعْدَاعِ، يُدْفَعُ بِعَصًا ذَاتِ شُعْبَتَيْنِ فِي النَّارِ. وَحَتَّى رَأَيْتُ فِيهَا صَاحِبَ الْمِحْجَنِ الَّذِي كَانَ يَسْرِقُ الْحَاجَّ بِمِحْجَنِهِ، مُتَّكِئًا عَلَى مِحْجَنِهِ فِي النَّارِ، يَقُولُ: "أَنَا سَارِقُ الْمِحْجَنِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): പ്രവാചക(സ)ന്റെ കാലത്ത് സൂര്യ ഗ്രഹണം ഉണ്ടായപ്പോൾ അവിടുന്ന് നിസ്കാരത്തിനു വേണ്ടി പുറപ്പെട്ടു. പ്രവാചക(സ)നോടൊപ്പം ഉള്ളവരും നിസ്കാരത്തിനായി നിന്നു. നബി(സ) ദീർഘമായി നിന്നു. പിന്നെ ദീർഘമായി റുകൂഅ് ചെയ്തു. പിന്നീട് തല ഉയർത്തി ദീർഘമായ സുജൂദ് ചെയ്തു. തുടർന്ന് തല ഉയർത്തി ദീർഘമായി ഇരുന്നു. വീണ്ടും ദീർഘമായ സുജൂദ് ചെയ്തു. പിന്നെ പ്രവാചകൻ(സ) തല ഉയർത്തുകയും നിൽക്കുകയും ചെയ്തു. ആദ്യത്തെ റക്അത്തിൽ ചെയ്തതു പോലെ തന്നെ രണ്ടാമത്തെ റക്അത്തിലും ചെയ്തു. നിർത്തം, റുകൂഅ്, സുജൂദ്, ഇരുത്തം എല്ലാറ്റിലും. രണ്ടാമത്തെ റക്അത്തിന്റെ അവസാനത്തെ സുജൂദിൽ ഊതുകയും കരയുകയും ചെയ്ത് ഇങ്ങനെ പറഞ്ഞു; "ഞാൻ അവർക്കിടയിൽ (ജനങ്ങൾക്ക്) ജീവിച്ചിരിക്കുന്ന അവസ്ഥയിൽ ഇങ്ങനെ ഒരു അവസ്ഥ ഉണ്ടാകുമെന്ന് നീ എനിക്ക് മുന്നറിയിപ്പ് തന്നിട്ടില്ല. ഞങ്ങൾ നിന്നോട് പാപ മോചനം തേടുന്ന അവസ്ഥയിൽ ഇങ്ങനെ ഒരു സംഭവം നീ എനിക്ക് മുന്നറിയിപ്പ് നൽകിയിട്ടില്ല." പിന്നെ പ്രവാചകൻ(സ) (സുജൂദിൽ നിന്ന്) തല ഉയർത്തി. സൂര്യൻ ഗ്രഹണ മുക്തമായി, അപ്പോൾ പ്രവാചകൻ(സ) ജനങ്ങളെ അഭിസംബോധന ചെയ്യുവാനായി എഴുന്നേറ്റ്നിന്നു. അല്ലാഹുവിനെ സ്തുതിക്കുകയും, അവനെ വാഴ്ത്തുകയും ചെയ്തു. തുടർന്ന് പറഞ്ഞു: "നിശ്ചയം, സൂര്യനും ചന്ദ്രനും അല്ലാഹുവിന്റെ ദൃഷ്ടാന്തങ്ങളിൽ പെട്ട രണ്ട് ദൃഷ്ടാന്തമാണ്. അവയിൽ ഏതെങ്കിലും ഒന്നിന് ഗ്രഹണം ബാധിച്ചതായി നിങ്ങൾ കണ്ടാൽ അല്ലാഹുവിന്റെ സ്മരണയിലേക്ക്(നിസ്കാരത്തിലേക്ക്) ധൃതിപ്പെടുവിൻ! മുഹമ്മദിന്റെ ആത്മാവ് ഏതൊരുവന്റെ അധികാരത്തിലാണോ അവൻ സത്യം, എന്റെ കൈ ഞാൻ നീട്ടുകയാണെങ്കിൽ (സ്വർഗ്ഗത്തിലെ) പഴക്കുലകളിൽ നിന്ന് എനിക്ക് പറിക്കാവുന്ന അവസ്ഥയിൽ സ്വർഗ്ഗത്തെ എന്നോട് അടുപ്പിക്കപ്പെട്ടു. നരകാഗ്നി നിങ്ങളിലേക്ക് പടർന്നു കയറുമോ എന്ന ഭയത്താൽ ഞാൻ അതിനെ ഒഴിവാക്കുവാൻ തുടങ്ങുന്ന അവസ്ഥയിൽ എത്തുന്നതു വരെ നിശ്ചയം, എന്റെ സമീപത്തേക്ക് അത് കൊണ്ടുവരപ്പെട്ടു. അങ്ങനെ ഒരു പൂച്ചയെ കെട്ടിയിട്ടതിനാൽ ശിക്ഷിക്കപ്പെടുന്ന ''ഹിംയർ'' ഗോത്രത്തിൽ പെട്ട ഒരു സ്ത്രീയെ ഞാൻ നരകത്തിൽ കണ്ടു. ഭൂമിയിലെ ഉണങ്ങിയ പുല്ലുകൾ തിന്നാൻ പോലും അവൾ അതിനെ വിട്ടില്ല. അതിനവൾ ഭക്ഷണവും വെള്ളവും നൽകിയതും ഇല്ല. അങ്ങനെ അത് ചത്തു. അവൾ മുന്നോട്ട് വന്നാൽ ആ പൂച്ച അവളെ മാന്തിക്കീറുന്ന അവസ്ഥയിലും അവൾ പിന്നോട്ട് വന്നാൽ അവളുടെ പിൻഭാഗം മാന്തിക്കീറുന്ന അവസ്ഥയിലും ഞാൻ കണ്ടു. ബനൂദ്ദഅ്ദാഇന്റെ സഹോദരൻ രോമമില്ലാത്ത തോൽ ചെരുപ്പുകാരനെയും ഞാൻ നരകത്തിൽ കണ്ടു. രണ്ട് ചില്ലകളുള്ള വടി കൊണ്ട് നരകത്തിൽ അയാൾ തള്ളപ്പെടുന്നു. ''മിഹ്ജൻ'' (അഗ്രം വളഞ്ഞ വടി) കാരനെയും അവിടെ കണ്ടു. ഹാജിമാരെ തന്റെ വടി ഉപയോഗിച്ച് അവൻ കൊള്ളയടിക്കുമായിരുന്നു. ''മിഹ്ജൻ'' കൊള്ളക്കാരൻ ഞാനാണ് എന്ന് പറഞ്ഞ് അവൻ നരകത്തിൽ തന്റെ വടിയും ഊന്നി നിൽക്കുന്നു. (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 638, 639, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا أَنَا يَوْمًا وَغُلَامٌ مِنَ الْأَنْصَارِ نَرْمِي غَرَضَيْنِ لَنَا، عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى إِذَا كَانَتِ الشَّمْسُ قِيدَ رُمْحَيْنِ أَوْ ثَلَاثَةٍ فِي عَيْنِ النَّاظِرِ مِنَ الْأُفُقِ اسْوَدَّتْ، فَقَالَ أَحَدُنَا لِصَاحِبِهِ: انْطَلِقْ بِنَا إِلَى الْمَسْجِدِ، فَوَاللَّهِ لَيُحْدِثَنَّ شَأْنُ هَذِهِ الشَّمْسِ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أُمَّتِهِ حَدَثًا، قَالَ: فَدَفَعْنَا إِلَى الْمَسْجِدِ، قَالَ: فَوَافَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ خَرَجَ إِلَى النَّاسِ، قَالَ: فَاسْتَقْدَمَ فَصَلَّى، فَقَامَ كَأَطْوَلِ قِيَامٍ قَامَ بِنَا فِي صَلَاةٍ قَطُّ، مَا نَسْمَعُ لَهُ صَوْتًا، ثُمَّ رَكَعَ بِنَا كَأَطْوَلِ رُكُوعٍ مَا رَكَعَ بِنَا فِي صَلَاةٍ قَطُّ مَا نَسْمَعُ لَهُ صَوْتًا ثُمَّ سَجَدَ بِنَا كَأَطْوَلِ سُجُودٍ مَا سَجَدَ بِنَا فِي صَلَاةٍ قَطُّ، لَا نَسْمَعُ لَهُ صَوْتًا، ثُمَّ فَعَلَ ذَلِكَ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ، قَالَ: فَوَافَقَ تَجَلِّي الشَّمْسِ جُلُوسَهُ فِي الرَّكْعَةِ الثَّانِيَةِ، فَسَلَّمَ، فَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ، وَشَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَشَهِدَ أَنَّهُ عَبْدُ اللَّهِ وَرَسُولُهُ. (د,ت,ن,جه)', 'സമുറത്തുബ്നു ജുൻദുബ്(റ): റസൂലി(സ)ന്റെ കാലത്ത് ഞാനും അൻസ്വാരികളിൽ പെട്ട ഒരു കുട്ടിയും ചേർന്ന് രണ്ട് ഉന്നം വെച്ചു എറിഞ്ഞുകൊണ്ടിരിക്കുകയായിരുന്നു. അങ്ങിനെ സൂര്യൻ ജന ദൃഷ്ടിയിൽ രണ്ടോ മൂന്നോ കുന്തത്തിന്റെ തോതിൽ ചക്രവാളത്തിൽ നിന്ന് ഉയർന്നപ്പോൾ കറുത്തു. അപ്പോൾ ഒരാൾ തന്റെ കൂട്ടുകാരനോട് പറഞ്ഞു; നമുക്ക് പള്ളിയിലേക്ക് പോകാം, അല്ലാഹുവാണെ, ഈ സൂര്യന്റെ അവസ്ഥ നബി(സ)യുടെ സമൂഹത്തിൽ ഒരു സംഭവം തന്നെ സൃഷ്ടിക്കും. അങ്ങിനെ ഞങ്ങൾ ചെന്നപ്പോൾ റസൂൽ(സ) ജനങ്ങൾക്കിടയിലേക്ക് ഇറങ്ങിവരുന്നതായി ഞങ്ങൾ കണ്ടു. നബി(സ) മുന്നോട്ട് വന്നു. നിസ്കരിച്ചു. ദീർഘ നേരം നിറുത്തത്തിൽ തുടർന്നു. നബി(സ)യുടെ ഒരു ശബ്ദവും ഞങ്ങൾ കേൾക്കുന്നില്ലായിരുന്നു. ശേഷം മുമ്പൊരു നിസ്കാരത്തിലും ഞങ്ങൾക്ക് (ഇമാമായി) റുകൂഅ് ചെയ്തിട്ടില്ലാത്തത്ര ദീർഘമായ റുകൂഅ് ചെയ്തു. പിന്നീട് മുമ്പൊരിക്കലും ഒരു സുജൂദിലും കഴിച്ചു കൂട്ടാത്തത്ര സമയം നബി(സ) സുജൂദിൽ ചിലവഴിച്ചു. സുജൂദിൽ വെച്ചും നബി(സ)യുടെ ഒരു ശബ്ദവും ഞങ്ങൾ കേൾക്കുന്നില്ലായിരുന്നു. രണ്ടാമത്തെ റക്അത്തും ഇതേ രീതിയിൽ നിർവ്വഹിച്ചു. നിവേദകൻ പറയുന്നു: രണ്ടാമത്തെ റക്അത്തിലെ നബി(സ)യുടെ ഇരുത്തവും സൂര്യൻ ഗ്രഹണത്തിൽ നിന്ന് മുക്തമായതും ഒരുമിച്ചായിരുന്നു. പിന്നെ നബി(സ) സലാം വീട്ടി. അല്ലാഹുവിനെ സ്തുതിച്ചു, അവനെ പുകഴ്ത്തി. അവനല്ലാതെ ആരാധ്യനില്ലെന്നും താൻ അവന്റെ അടിമയും ദൂതനുമാണെന്നും സാക്ഷ്യപ്പെടുത്തുകയും ചെയ്തു. (ദ,തു,ന,ജ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറത്തുബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 639, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ قَبِيصَةَ الْهِلَالِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ الشَّمْسَ انْخَسَفَتْ، فَصَلَّى نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ رَكْعَتَيْنِ حَتَّى انْجَلَتْ، ثُمَّ قَالَ: "إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ، وَلَكِنَّهُمَا خَلْقَانِ مِنْ خَلْقِهِ، وَإِنَّ اللَّهَ عَزَّ وَجَلَّ يُحْدِثُ فِي خَلْقِهِ مَا شَاءَ، وَإِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا تَجَلَّى لِشَيْءٍ مِنْ خَلْقِهِ يَخْشَعُ لَهُ، فَأَيُّهُمَا حَدَثَ فَصَلُّوا حَتَّى يَنْجَلِيَ، أَوْ يُحْدِثَ اللَّهُ أَمْرًا". (ن)', 'ഖബീസാ ഹിലാലി(റ): സൂര്യന് ഗ്രഹണം ഉണ്ടായി. സൂര്യൻ പൂർണ്ണമായി വെളിവാകുന്നത് വരെ രണ്ട് റക്അത്തുകൾ വീതം നിസ്കരിച്ച ശേഷം നബി(സ) പറഞ്ഞു: "തീർച്ചയായും ആരുടെയെങ്കിലും മരണമോ ജനനമോ കാരണമായി സൂര്യനും ചന്ദ്രനും ഗ്രഹണം ബാധിക്കുകയില്ല. എന്നാൽ അത് രണ്ടും അല്ലാഹുവിന്റെ സൃഷ്ടികളിൽ പെട്ട രണ്ട് സൃഷ്ടികളാണ്. അല്ലാഹു അവന്റെ സൃഷ്ടികളിൽ അവൻ ഉദ്ദേശിച്ച മാറ്റങ്ങൾ സൃഷ്ടിക്കുന്നു. അല്ലാഹു ഒരുസൃഷ്ടിക്ക് വെളിവായാൽ ആ സൃഷ്ടി അവനെ ഭയക്കുന്നു. ഇവയിലൊന്ന് സംഭവിച്ചാൽ നിങ്ങൾ നമസ്കരിക്കുക, അതു ശരിയാകുന്നതുവരെ അല്ലെങ്കിൽ അല്ലാഹു ഒരു മാർഗ്ഗമുണ്ടാക്കുന്നതുവരെ" (ന)', 'قَبِيصَةَ الْهِلَالِيِّ', 'ഖബീസാ ഹിലാലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ خَرَجَ يَوْمًا مُسْتَعْجِلًا إِلَى الْمَسْجِدِ، وَقَدِ انْكَسَفَتِ الشَّمْسُ، فَصَلَّى حَتَّى انْجَلَتْ، ثُمَّ قَالَ: "إِنَّ أَهْلَ الْجَاهِلِيَّةِ كَانُوا يَقُولُونَ: إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْخَسِفَانِ إِلَّا لِمَوْتِ عَظِيمٍ مِنْ عُظَمَاءِ أَهْلِ الْأَرْضِ. وَإِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ، وَلَا لِحَيَاتِهِ، وَلَكِنَّهُمَا خَلِيقَتَانِ مِنْ خَلْقِهِ، يُحْدِثُ اللَّهُ فِي خَلْقِهِ مَا يَشَاءُ، فَأَيُّهُمَا انْخَسَفَ فَصَلُّوا حَتَّى يَنْجَلِيَ، أَوْ يُحْدِثَ اللَّهُ أَمْرًا". (ن)', 'നുഅ്നാനുബ്നു ബഷീർ(റ): സൂര്യ ഗ്രഹണം ബാധിച്ച ദിവസം നബി(സ) ധൃതിയിൽ പള്ളിയിലേക്ക് പുറപ്പെടുകയും സൂര്യൻ പൂർണ്ണമായി വെളിവാകുന്നത് വരെ നിസ്കരിക്കുകയും ചെയ്ത ശേഷം നബി(സ) പറഞ്ഞു: "തീർച്ചയായും ജാഹിലിയ്യാകാലത്തെ ആളുകൾ പറയുമായിരുന്നു: ഭൂമുഖത്തെ നല്ല വ്യക്തികളിൽ നിന്ന് (ആരെങ്കിലും) മരിക്കുന്നതു കാരണമായിട്ടല്ലാതെ സൂര്യനും ചന്ദ്രനും ഗ്രഹണം ബാധി ക്കുകയില്ല. എന്നാൽ ആരുടെയും മരണവും ജീവിതവും കാരണമായി സൂര്യനും ചന്ദനും ഗ്രഹണം ബാധിക്കുകയില്ല. എന്നാൽ അത് രണ്ടും അല്ലാഹുവിന്റെ സൃഷ്ടികളാണ്. അവന്റെ സൃഷ്ടികളിൽ അവൻ ഉദ്ദ്യേശിച്ച മാറ്റങ്ങൾ സൃഷ്ടിക്കുന്നതാണ്. ആയതിനാൽ അവ രണ്ടിൽ നിന്ന് ഏതിന് ഗ്രഹണം കണ്ടാലും (ഗ്രഹണം കഴിഞ്ഞ്) സൂര്യൻ പൂർണ്ണമായി വെളിവാകുന്നത് വരെയോ അല്ലാഹു ഒരു (മറ്റൊരു) കാര്യം നടപ്പിൽ വരുത്തുന്നതു വരെയോ നിങ്ങൾ നിസ്കരിക്കുവിൻ." (ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്നാനുബ്നു ബഷീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 640, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى رَكْعَتَيْنِ مِثْلَ صَلَاتِكُمْ هَذِهِ، وَذَكَرَ كُسُوفَ الشَّمْسِ. (ن)', 'അബൂബക്റ(റ): നിങ്ങളുടെ ഈ നിസ്കാരം പോലെ നബി(സ) രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. തുടർന്ന് സൂര്യ ഗ്രഹണത്തെപ്പറ്റി പറയുകയും ചെയ്തു. (ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 641, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَبْدِاللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: انْخَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ قِيَامًا طَوِيلًا نَحْوًا مِنْ قِرَاءَةِ سُورَةِ الْبَقَرَةِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا، ثُمَّ رَفَعَ فَقَامَ قِيَامًا طَوِيلًا وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ سَجَدَ، ثُمَّ قَامَ قِيَامًا طَوِيلًا وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ رَفَعَ فَقَامَ قِيَامًا طَوِيلًا وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ سَجَدَ، ثُمَّ انْصَرَفَ، وَقَدْ تَجَلَّتِ الشَّمْسُ، فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ فَاذْكُرُوا اللَّهَ". قَالُوا: يَا رَسُولَ اللَّهِ، رَأَيْنَاكَ تَنَاوَلْتَ شَيْئًا فِي مَقَامِكَ، ثُمَّ رَأَيْنَاكَ كَعْكَعْتَ، قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي رَأَيْتُ الْجَنَّةَ، فَتَنَاوَلْتُ عُنْقُودًا، وَلَوْ أَصَبْتُهُ لَأَكَلْتُمْ مِنْهُ مَا بَقِيَتِ الدُّنْيَا، وَأُرِيتُ النَّارَ، فَلَمْ أَرَ مَنْظَرًا كَالْيَوْمِ قَطُّ أَفْظَعَ، وَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ، قَالُوا: بِمَ يَا رَسُولَ اللَّهِ؟ قَالَ: "بِكُفْرِهِنَّ". قِيلَ: يَكْفُرْنَ بِاللَّهِ؟ قَالَ: "يَكْفُرْنَ الْعَشِيرَ، وَيَكْفُرْنَ الْإِحْسَانَ، لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ كُلَّهُ، ثُمَّ رَأَتْ مِنْكَ شَيْئًا، قَالَتْ: مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ". (خ,ن)', 'അബ്ദില്ലാഹിബ്നു അബ്ബാസ്(റ): സൂര്യന് ഗ്രഹണം ബാധിച്ചപ്പോൾ റസൂൽ(സ) (ഇമാമായി) നിസ്കരിച്ചു, ജനങ്ങളും നബി(സ)യോടൊപ്പം ഉണ്ട്. നബി(സ) സുദീർഘമായി നിന്നു. സൂറത്തുൽ ബഖറയോളം നബി(സ) ഓതി. നിവേദകൻ പറയുന്നു: പിന്നെ പ്രവാചകൻ(സ) നീണ്ട റുകൂഅ് ചെയ്യുകയും ശേഷം ഉയരുകയും ദീർഘമായി നിൽക്കുകയും ചെയ്തു. അത് ആദ്യത്തെ നിർത്തത്തേക്കാൾ കുറഞ്ഞതായിരുന്നു. പിന്നെ തിരുമേനി(സ) നീണ്ട റുകൂഅ് ചെയ്തു. അത് ആദ്യത്തെ റുകൂഇനേക്കാൾ കുറവായിരുന്നു. പിന്നീട് നബി(സ) സുജൂദ് ചെയ്തു. ശേഷം ദീർഘമായി നിന്നു. അത് ആദ്യത്തേതിനേക്കാൾ കുറവായിരുന്നു. പിന്നീട് ദീർഘമായ റുകൂഅ് ചെയ്തു. അത് ആദ്യത്തെ റുകൂഇനേക്കാൾ കുറവായിരുന്നു. പിന്നെ ഉയരുകയും ദീർഘമായി നിൽക്കുകയും ചെയ്തു. അത് ആദ്യത്തെ നിർത്തത്തേക്കാൾ കുറവായിരുന്നു. പിന്നെ തിരുമേനി നീണ്ട റുകൂഅ് ചെയ്തു. അത് ആദ്യത്തെ റുകൂഇനേക്കാൾ ദൈർഘ്യം കുറവായിരുന്നു. പിന്നീട് സുജൂദ് ചെയ്യുകയും നിസ്കാരത്തിൽ നിന്ന് വിരമിക്കുകയും ചെയ്തു, അപ്പോൾ സൂര്യനും തെളിഞ്ഞിരുന്നു. പ്രവാചകൻ(സ) പറഞ്ഞു: "തീർച്ചയായും സൂര്യനും ചന്ദ്രനും അല്ലാഹുവിന്റെ ദൃഷ്ടാന്തങ്ങളിൽപെട്ട രണ്ട് ദൃഷ്ടാന്തമാണ്, ആരുടേയും ജനന മരണ കാരണമായി അവ രണ്ടിനും ഗ്രഹണം ഉണ്ടാകുന്നില്ല. ആയതിനാൽ നിങ്ങൾ അതിനെ (ഗ്രഹണത്തെ) കണ്ടാൽ അല്ലാഹുവിനെ ഓർക്കുവിൻ! (നിസ്കരിക്കുവിൻ)" അനുചരർ ചോദിച്ചു: അല്ലാഹുവിന്റെ പ്രവാചകരെ, അവിടുന്ന് നിൽക്കുന്ന ഈ സ്ഥാനത്ത് നിന്ന് എന്തോ ഒരു വസ്തുവിനെ പിടിച്ചെടുക്കുന്നതായും, പിന്നീട് പിന്നോട്ട് മാറുന്നതായും ഞങ്ങൾ കണ്ടുവല്ലോ? പ്രവാചകൻ(സ) പറഞ്ഞു: "നിശ്ചയം, ഞാൻ സ്വർഗ്ഗം കണ്ടു. (സ്വർഗ്ഗം എനിക്കു കാണിക്കപ്പെട്ടു) അപ്പോൾ സ്വർഗ്ഗത്തിൽ നിന്ന് ഒരു പഴക്കുല എത്തിപ്പിടിക്കാൻ ഞാൻ ശ്രമിച്ചു. അത് ഞാൻ പിടിച്ചിരുന്നെങ്കിൽ ഈ ലോകം ശേഷിക്കുവോളം കാലം തീർച്ചയായും നിങ്ങൾ അതിൽ നിന്ന് ഭക്ഷിക്കുമായിരുന്നു. ഞാൻ, നരകത്തെയും കണ്ടു. ഇന്നത്തെ പോലെ (മോശമായ) ദൃശ്യം ഞാൻ ഒരിക്കലും കണ്ടിട്ടില്ല. നരകവാസികളിലധികം സ്ത്രീകളായും ഞാൻ കണ്ടു." അനുചരന്മാർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അത് എന്തു കൊണ്ടാണ്? റസൂൽ(സ) പറഞ്ഞു: "അവരുടെ നിഷേധ സ്വഭാവം കാരണമായി". അപ്പോൾ ചോദിക്കപ്പെട്ടു. അവർ അല്ലാഹുവിനെ നിഷേധിക്കുന്നുവോ? നബി(സ) പറഞ്ഞു: " ഭർത്താക്കന്മാരെ അവർ ധിക്കരിക്കുന്നു; നന്ദികേട് കാണിക്കുന്നു. ഉള്ള കാലമത്രയും ഒരു പെണ്ണിന് നീ ഉപകാരം ചെയ്ത് (പിന്നീട് ഏതെങ്കിലും ഒരു സന്ദർഭത്തിൽ) നിന്നിൽ നിന്നൊരു വീഴ്ചയുണ്ടായാൽ അവൾ പറയും, ഒരിക്കലും നിന്നിൽ നിന്നൊരു ഗുണവും എനിക്ക് കിട്ടിയിട്ടില്ല." (ബു,ന)', 'عَبْدِاللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദില്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 641, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=0 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُسِفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّى بِالنَّاسِ فَقَامَ، فَحَزَرْتُ قِرَاءَتَهُ فَرَأَيْتُ أَنَّهُ قَرَأَ بِسُورَةِ الْبَقَرَةِ،... وَسَاقَ الْحَدِيثَ، ثُمَّ سَجَدَ سَجْدَتَيْنِ، ثُمَّ قَامَ فَأَطَالَ الْقِرَاءَةَ، فَحَزَرْتُ قِرَاءَتَهُ أَنَّهُ قَرَأَ بِسُورَةِ آلِ عِمْرَانَ. وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ قِرَاءَةً طَوِيلَةً، فَجَهَرَ بِهَا. يَعْنِي فِي صَلَاةِ الْكُسُوفِ. (د)', 'ആഇശ(റ): പ്രവാചക(സ)ന്റെ കാലത്ത് സൂര്യ ഗ്രഹണം ഉണ്ടായപ്പോൾ പള്ളിയിലേക്ക് പോവുകയും ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കാൻ പ്രവാചകൻ(സ) നിൽക്കുകയും ചെയ്തു. അപ്പോൾ തിരുമേനി(സ)യുടെ നിർത്തത്തെപ്പറ്റി ഞാൻ ഊഹിച്ചു നോക്കി. സൂറത്തുൽ ബഖറയായിരിക്കണം അവിടുന്ന് ഓതിയത്. ഹദീസ് തുടരുന്നു; പിന്നീട് പ്രവാചകൻ(സ) രണ്ട് സുജൂദ് ചെയ്യുകയും വീണ്ടും നിൽക്കുകയും ഖുർആൻ പാരായണം ദീർഘിപ്പിക്കുകയും ചെയ്തു. അപ്പോഴും പ്രവാചക(സ)ന്റെ പാരായണം ഞാൻ കണക്കാക്കി നോക്കി. ആലുഇംറാൻ സൂറത്ത് ആയിരിക്കണം അവിടുന്ന് പാരായണം ചെയ്തത്. മറ്റൊരു നിവേദനം: നിശ്ചയം, റസൂൽ(സ) ദീർഘമായി, ഉറക്കെ ഓതി. അതായത് സൂര്യഗ്രഹണ നിസ്കാരത്തിൽ. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 642, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=24 and h.hadith_no=15), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ قِرَاءَةً طَوِيلَةً، فَجَهَرَ بِهَا. يَعْنِي فِي صَلَاةِ الْكُسُوفِ. (د)', 'മറ്റൊരു നിവേദനം: നിശ്ചയം, റസൂൽ(സ) ദീർഘമായി, ഉറക്കെ ഓതി. അതായത് സൂര്യഗ്രഹണ നിസ്കാരത്തിൽ. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: جَهَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الْخُسُوفِ بِقِرَاءَتِهِ، فَإِذَا فَرَغَ مِنْ قِرَاءَتِهِ كَبَّرَ، فَرَكَعَ وَإِذَا رَفَعَ مِنَ الرَّكْعَةِ، قَالَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ". ثُمَّ يُعَاوِدُ الْقِرَاءَةَ فِي صَلَاةِ الْكُسُوفِ، أَرْبَعَ رَكَعَاتٍ فِي رَكْعَتَيْنِ، وَأَرْبَعَ سَجَدَاتٍ. (خ,ن)', 'ആഇശ(റ): ഗ്രഹണ നിസ്കാരത്തിൽ പ്രവാചകൻ(സ) ഉച്ചത്തിൽ ഓതി. ഖുർആൻ പാരായണം കഴിഞ്ഞ് തക്ബീർ ചൊല്ലി റുകൂഅ് ചെയ്തു. റുകൂഇൽ നിന്ന് ഉയർന്നപ്പോൾ പ്രവാചകൻ ''സമിഅല്ലാഹു ലിമൻ ഹമിദ, റബ്ബനാ ലകൽ ഹംദു'' എന്ന് പറഞ്ഞു. സൂര്യ ഗ്രഹണ നിസ്കാരത്തിൽ നബി(സ) വീണ്ടും ഖുർആൻ പാരായണം ചെയ്യാറുണ്ടായിരുന്നു. രണ്ട് റക്അത്തിൽ നാല് റുകൂഉകളും നാലു സുജൂദുകളും. (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 642, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ صَلَّى أَرْبَعَ رَكَعَاتٍ فِي أَرْبَعِ سَجَدَاتٍ، وَجَهَرَ فِيهَا بِالْقِرَاءَةِ، كُلَّمَا رَفَعَ رَأْسَهُ قَالَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ". (ن)', 'ആഇശ(റ) റസൂലി(സ)ന്റെ നിന്നും റിപ്പോർട്ട് ചെയ്യുന്നു. അവിടുന്ന് നാലു സുജൂദുകളും നാല് റുകൂഉകളുമായി നിസ്കരിക്കുകയും അതിൽ ഉറക്കെ ഓതുകയും ചെയ്തു. (റുകൂഇൽ നിന്ന്) പ്രവാചകൻ(സ) തല ഉയർത്തുമ്പോഴെല്ലാം ''സമിഅല്ലാഹു ലിമൻ ഹമിദ, റബ്ബനാ വലകൽഹംദു'' എന്ന് പഞ്ഞിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 642, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: خَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنَادِيًا يُنَادِي: أَنِ الصَّلَاةَ جَامِعَةً، فَاجْتَمِعُوا، وَاصْطَفُّوا، فَصَلَّى بِهِمْ أَرْبَعَ رَكَعَاتٍ فِي رَكْعَتَيْنِ وَأَرْبَعَ سَجَدَاتٍ. (م,د,ن)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ കാലത്ത് സൂര്യഗ്രഹണമുണ്ടായപ്പോൾ വിളിച്ചറിയിക്കുന്ന ഒരാളോട് ''അസ്സ്വലാത്തു ജാമിഅ'' എന്ന് വിളിച്ചറിയിക്കുവാൻ നബി(സ) പറഞ്ഞു. അപ്പോൾ അവർ (സഹാബികൾ) കൂട്ടം ചേരുകയും സ്വഫ്ഫായി നിൽക്കുകയും ചെയ്തു. അപ്പോൾ രണ്ട് റകഅത്തിൽ നാല് റുകൂഉം, നാലു സുജൂദുമായി പ്രവാചകൻ(സ) അവർക്ക് (ഇമാമായി) നിസ്കരിച്ചു. (മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 643, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَسْمَاءَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَقَدْ أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعَتَاقَةِ فِي كُسُوفِ الشَّمْسِ. (خ,د)', 'അസ്മാഅ്ബിൻത് അബീബക്കർ(റ): സൂര്യഗ്രഹണ വേളയിൽ അടിമകളെ സ്വതന്ത്രരാക്കുവാൻ നബി(സ) കൽപിച്ചിരുന്നു. (ബു,ദ)', 'أَسْمَاءَ', 'അസ്മാഅ്ബിൻത് അബീബക്കർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 643, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ يَهُودِيَّةً أَتَتْهَا فَقَالَتْ: أَجَارَكِ اللَّهُ مِنْ عَذَابِ الْقَبْرِ. قَالَتْ عَائِشَةُ: يَا رَسُولَ اللَّهِ، إِنَّ النَّاسَ لَيُعَذَّبُونَ فِي الْقُبُورِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَائِذًا بِاللَّهِ". قَالَتْ عَائِشَةُ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مَخْرَجًا، فَخَسَفَتِ الشَّمْسُ، فَخَرَجْنَا إِلَى الْحُجْرَةِ، فَاجْتَمَعَ إِلَيْنَا نِسَاءٌ، وَأَقْبَلَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَلِكَ ضَحْوَةً، فَقَامَ قِيَامًا طَوِيلًا، ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا، ثُمَّ رَفَعَ رَأْسَهُ فَقَامَ دُونَ الْقِيَامِ الْأَوَّلِ، ثُمَّ رَكَعَ دُونَ رُكُوعِهِ، ثُمَّ سَجَدَ، ثُمَّ قَامَ الثَّانِيَةَ، فَصَنَعَ مِثْلَ ذَلِكَ إِلَّا أَنَّ رُكُوعَهُ وَقِيَامَهُ دُونَ الرَّكْعَةِ الْأُولَى، ثُمَّ سَجَدَ. وَتَجَلَّتِ الشَّمْسُ، فَلَمَّا انْصَرَفَ قَعَدَ عَلَى الْمِنْبَرِ، فَقَالَ فِيمَا يَقُولُ: "إِنَّ النَّاسَ يُفْتَنُونَ فِي قُبُورِهِمْ كَفِتْنَةِ الدَّجَّالِ". قَالَتْ عَائِشَةُ: كُنَّا نَسْمَعُهُ بَعْدَ ذَلِكَ يَتَعَوَّذُ مِنْ عَذَابِ الْقَبْرِ. وَفِي رِوَايَةٍ: ثُمَّ أَمَرَهُمْ أَنْ يَتَعَوَّذُوا مِنْ عَذَابِ الْقَبْرِ. (خ,ن)', 'ആഇശ(റ): ഒരു ജൂത സ്ത്രീ ആഇശ(റ)യുടെ അടുക്കൽ വന്നു. ആ സ്ത്രീ പറഞ്ഞു: ഖബർ ശിക്ഷയിൽ നിന്നും നിങ്ങളെ അല്ലാഹു കാക്കട്ടെ, ആഇശ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, ഖബറുകളിൽ ജനങ്ങൾ ശിക്ഷിക്കപ്പെടുമോ? അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹുവിനോട് കാവൽ" (തേടുന്നു) ആഇശ(റ) പറയുന്നു: നബി(സ) ഒരു വഴിക്ക് പുറപ്പെട്ടു. അപ്പോൾ സൂര്യന് ഗ്രഹണം ബാധിച്ചു. അപ്പോൾ ഞങ്ങൾ മുറിയിലേക്ക് പുറപ്പെട്ടു. സ്ത്രീകൾ ഞങ്ങളുടെ അടുക്കൽ ഒരുമിച്ചു കൂടി. റസൂൽ(സ) ഞങ്ങളിലേക്ക് വരികയും ചെയ്തു. അത് ളുഹാ (നിസ്കാരത്തിന്റെ) സമയം ആയിരുന്നു. അപ്പോൾ (നിസ്കാരത്തിൽ) ദീർഘമായ നിർത്തം നിന്നു. പിന്നെ നബി(സ) ദീർഘമായി റുകൂഅ് ചെയ്തു. പിന്നെ തല ഉയർത്തി. തുടർന്ന് ആദ്യത്തേതിനേക്കാൾ കുറഞ്ഞ നിർത്തം നിന്നു. പിന്നെ ആദ്യത്തെ റുകൂഇനേക്കാൾ ചുരുങ്ങിയ നിലയിൽ റുകൂഅ് ചെയ്തു. ശേഷം സുജൂദ് നിർവ്വഹിച്ചു. പിന്നെ രണ്ടാം റക്അത്തിലേക്ക് നിന്ന നബി(സ) ആദ്യത്തെ റക്അത്തു പോലെ തന്നെ പ്രവർത്തിച്ചു. പക്ഷെ, പ്രവാചക(സ)ന്റെ നിർത്തവും റുകൂഉം ആദ്യത്തേതിനേക്കാൾ കുറഞ്ഞതായിരുന്നു. പിന്നെ സുജൂദ് ചെയ്തു. സൂര്യൻ പ്രത്യക്ഷപ്പെടുകയും ചെയ്തു. നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചപ്പോൾ മിമ്പറിൽ ഇരുന്നു. പ്രവാചകൻ(സ) പറഞ്ഞിരുന്ന ഉപദേശത്തിൽ അപ്പോൾ പറഞ്ഞു:"നിശ്ചയം, ജനങ്ങൾ അവരുടെ ഖബറുകളിൽ കുഴപ്പത്തിൽ അകപ്പെടുത്തപ്പെടും ദജ്ജാലിന്റെ കുഴപ്പം പോലെ (ദജ്ജാൽ ജനങ്ങളെ കുഴപ്പത്തിൽ ആക്കുന്നത് പോലെ...) ആഇശ(റ) പറഞ്ഞു: ഇതിന് ശേഷം ഖബറിലെ ശിക്ഷയിൽ നിന്ന് നബി(സ) കാവൽ തേടുന്നതായി ഞങ്ങൾ കേൾക്കുമായിരുന്നു. മറ്റൊരു നിവേദനം: ശേഷം ഖബ്റിലെ ശിക്ഷയിൽനിന്ന് കാവൽ ചോദിക്കാൻ അവിടുന്ന് അവരോട് കൽപിച്ചു. (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 643, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=24 and h.hadith_no=20), 1, 'وَفِي رِوَايَةٍ: ثُمَّ أَمَرَهُمْ أَنْ يَتَعَوَّذُوا مِنْ عَذَابِ الْقَبْرِ. (خ,ن)', 'മറ്റൊരു നിവേദനം: ശേഷം ഖബ്റിലെ ശിക്ഷയിൽനിന്ന് കാവൽ ചോദിക്കാൻ അവിടുന്ന് അവരോട് കൽപിച്ചു. (ബു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَطَالَ الْقِيَامَ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ رَفَعَ فَأَطَالَ، قَالَ شُعْبَةُ: وَأَحْسَبُهُ قَالَ فِي السُّجُودِ نَحْوَ ذَلِكَ. وَجَعَلَ يَبْكِي فِي سُجُودِهِ وَيَنْفُخُ، وَيَقُولُ: "رَبِّ لَمْ تَعِدْنِي هَذَا، وَأَنَا أَسْتَغْفِرُكَ لَمْ تَعِدْنِي هَذَا وَأَنَا فِيهِمْ". فَلَمَّا صَلَّى قَالَ: "عُرِضَتْ عَلَيَّ الْجَنَّةُ، حَتَّى لَوْ مَدَدْتُ يَدِي تَنَاوَلْتُ مِنْ قُطُوفِهَا، وَعُرِضَتْ عَلَيَّ النَّارُ، فَجَعَلْتُ أَنْفُخُ خَشْيَةَ أَنْ يَغْشَاكُمْ حَرُّهَا. وَرَأَيْتُ فِيهَا سَارِقَ بَدَنَتَيْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَرَأَيْتُ فِيهَا أَخَا بَنِي دُعْدُعٍ سَارِقَ الْحَجِيجِ، فَإِذَا فُطِنَ لَهُ قَالَ: هَذَا عَمَلُ الْمِحْجَنِ، وَرَأَيْتُ فِيهَا امْرَأَةً طَوِيلَةً سَوْدَاءَ، تُعَذَّبُ فِي هِرَّةٍ رَبَطَتْهَا، فَلَمْ تُطْعِمْهَا وَلَمْ تَسْقِهَا وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ خَشَاشِ الْأَرْضِ حَتَّى مَاتَتْ. وَإِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، وَلَكِنَّهُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ، فَإِذَا انْكَسَفَتْ إِحْدَاهُمَا – أَوْ قَالَ: فَعَلَ أَحَدُهُمَا شَيْئًا مِنْ ذَلِكَ – فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ عَزَّ وَجَلَّ". (ن)', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ): നബി(സ)യുടെ കാലത്ത് സൂര്യന് ഗ്രഹണം ബാധിച്ചു. അപ്പോൾ നബി(സ) നിസ്കരിച്ചു. (നിസ്കാരത്തിലെ) നിർത്തം ദീർഘിപ്പിച്ചു. പിന്നീട് അവിടുന്ന് റുകൂഅ് ചെയ്യുകയും റുകൂഇനെ ദീർഘിപ്പിക്കുകയും ചെയ്തു. ശേഷം (റുകൂഇൽ നിന്ന്) ഉയരുകയും, (നിർത്തത്തെ) ദീർഘിപ്പിക്കുകയും ചെയ്തു. (ഹദീസ് നിവേദകരിൽപ്പെട്ട) ശുഅ്ബ പറയുന്നു: സുജൂദിന്റെ കാര്യത്തിലും അപ്രകാരം (റുകൂഅ് പോലെ) തന്നെ. നബി(സ) സുജൂദിൽ കരയുകയും, ഊതുകയും ചെയ്ത ശേഷം പറഞ്ഞു: "(എന്റെ രക്ഷിതാവേ ഞാൻ) നിന്നോട് പാപം പൊറുക്കലിനെ തേടുന്ന അവസ്ഥയിൽ ഇത്തരം ഒരു കാര്യത്തെപ്പറ്റി, ഞാൻ അവർക്കിടയിൽ ഉണ്ടായിരിക്കുന്ന അവസ്ഥയിൽ ഇതിനെപ്പറ്റി നീ എന്നെ ഭയപ്പെടുത്തിയിട്ടില്ല". നിസ്കാരം കഴിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു; "സ്വർഗ്ഗം എനിക്ക് കാണിക്കപ്പെട്ടു, (എത്രത്തോളം സമീപത്തെന്നാൽ) എന്റെ കൈ ഞാൻ നീട്ടിയിരുന്നെങ്കിൽ സ്വർഗ്ഗത്തിലെ പഴക്കുലകളിൽ നിന്ന് ഞാൻ എത്തിപ്പിടിക്കുമായിരുന്നു. നരകവും എനിക്ക് കാണിക്കപ്പെട്ടു, അപ്പോൾ നരകത്തിന്റെ ചൂട് നിങ്ങളിലേക്ക് എത്തുമോ എന്ന ഭയത്താൽ ഞാൻ ഊതുവാൻ തുടങ്ങി, റസൂലി(സ)ന്റെ രണ്ട് ഒട്ടകത്തെ മോഷ്ടിച്ചവനെയും ഞാൻ നരകത്തിൽ കണ്ടു, ഹജ്ജിനു വരുന്നവരുടെ വസ്തുക്കൾ മോഷ്ടിക്കുന്ന ''ബനൂ ദുഅ്ദുഇന്റെ സഹോദരനെ''യും ഞാൻ നരകത്തിൽ കണ്ടു. അയാൾക്ക് കാര്യം മനസ്സിലായപ്പോൾ അയാൾ പറഞ്ഞു: ഇത് തല വളഞ്ഞ വടിയുടെ പ്രവർത്തന(ഫല)മാണ്. നരകത്തിൽ കറുത്തു നീണ്ട ഒരു സ്ത്രീയേയും ഞാൻ കണ്ടു. ഒരു പൂച്ചയെ കെട്ടിയിട്ട വിഷയത്തിൽ അവൾക്ക് ശിക്ഷ നൽകപ്പെടുന്നു. അവൾ അതിന് ഭക്ഷണമോ, വെള്ളമോ നൽകിയില്ല. ഭൂമിയിലെ ഉണക്ക പുല്ല് തിന്നാൻ അനുവദിക്കാതെ, അത് ചാകുന്നത് വരെ അവൾ അതിനെ അഴിച്ച് വിട്ടതുമില്ല. തീർച്ചയായും സൂര്യന്നും ചന്ദ്രന്നും ആരുടേയും മരണ കാരണമായോ ജനന കാരണമായോ ഗ്രഹണം ബാധിക്കുന്നില്ല. എന്നാൽ അവ രണ്ടും അല്ലാഹുവിന്റെ ദൃഷ്ടാന്തങ്ങളിൽ പെട്ട രണ്ട് ദൃഷ്ടാന്തങ്ങളാണ്, അവ രണ്ടിലൊന്നിന് ഗ്രഹണം ബാധിച്ചാൽ - അല്ലെങ്കിൽ നബി(സ) പറഞ്ഞതിങ്ങനെയാണ്: അവ രണ്ടിൽ ഒന്നിന് ഗ്രഹണ സംബന്ധമായ വല്ലതും സംഭവിച്ചാൽ നിങ്ങൾ അല്ലാഹുവിന്റെ സ്മരണയിലേക്ക് (നിസ്കാരം) ധൃതിപ്പെടുവിൻ." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 644, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عن أبي بكرة رضي الله عنه قال: كنا عند رسول الله صلى الله عليه وسلم فانكسفت الشمس، فخرج رسول الله صلى الله عليه وسلم يجر رداءه حتى انتهى إلى المسجد، وثاب إليه الناس، فصلى بنا ركعتين، فلما انكشفت الشمس قال: "إن الشمس والقمر آيتان من آيات الله، يخوف الله عز وجل بهما عباده، وإنهما لا يخسفان لموت أحد ولا لحياته، فإذا رأيتم ذلك فصلوا حتى يكشف ما بكم". وذلك أن ابنا له مات يقال له إبراهيم، فقال له ناس في ذلك. (خ,ن)', 'അബൂബക്റ(റ): ഞങ്ങൾ നബി(സ)യുടെ അടുക്കലായിരിക്കെ, സൂര്യ ഗ്രഹണം ഉണ്ടായി. നബി(സ) മേൽവസ്ത്രം വലിച്ചിഴച്ച് പള്ളിയിലേക്കെത്തി. നബി(സ)യുടെ പിന്നാലെ ജനങ്ങളും എത്തി. തിരുമേനി(സ) ഞങ്ങൾക്ക് ഇമാമായി രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്തു. തുടർന്ന് സൂര്യൻ തെളിഞ്ഞപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "തീർച്ചയായും സൂര്യനും ചന്ദ്രനും അല്ലാഹുവിന്റെ ദൃഷ്ടാന്തങ്ങളിൽ പെട്ട രണ്ട് ദൃഷ്ടാന്തങ്ങളാണ്. അവ മുഖേന അല്ലാഹു അവന്റെ ദാസന്മാരെ ഭയപ്പെടുത്തുന്നു. അവ രണ്ടിനും ആരുടെയും ജനന മരണങ്ങൾ കാരണമായി ഗ്രഹണം ബാധിക്കുകയില്ല. ആയതിനാൽ നിങ്ങൾ ഗ്രഹണം കണ്ടാൽ നിങ്ങൾക്ക് വന്നു പെട്ടത് ഒഴിവാകുന്നതു വരെ നിസ്കരിക്കുവിൻ." ഈ സംഭവം നബി(സ)യുടെ ഇബ്രാഹീം എന്ന കുട്ടി മരിച്ചസന്ദർഭത്തിലായിരുന്നു. ആ കുട്ടിയുടെ മരണം കാരണമായാണ് ഗ്രഹണം ഉണ്ടായതെന്ന് ചിലർ പ്രവാചക(സ)നോട് പറഞ്ഞു. (ബു,ന)', 'أبي بكرة', 'അബൂബക്റ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: انْكَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِهِمْ، فَقَرَأَ بِسُورَةٍ مِنَ الطُّوَلِ، وَرَكَعَ خَمْسَ رَكَعَاتٍ، وَسَجَدَ سَجْدَتَيْنِ، ثُمَّ قَامَ الثَّانِيَةَ فَقَرَأَ سُورَةً مِنَ الطُّوَلِ، وَرَكَعَ خَمْسَ رَكَعَاتٍ، وَسَجَدَ سَجْدَتَيْنِ، ثُمَّ جَلَسَ كَمَا هُوَ مُسْتَقْبِلَ الْقِبْلَةِ يَدْعُو حَتَّى انْجَلَى كُسُوفُهَا. (د)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ)യുടെ കാലത്ത് സൂര്യ ഗ്രഹണം ഉണ്ടായി. നബി(സ) അനുചരർക്ക് ഇമാമായി നിസ്കരിച്ചു. അപ്പോൾ ദീർഘമായ ഒരു സൂറത്ത് ഓതി. അഞ്ച് റുകൂഉകളും, രണ്ട് സുജൂദും നിർവ്വഹിച്ചു. പിന്നീട് രണ്ടാം റക്അത്തിലേക്ക് കടന്ന് ദീർഘമായ സൂറത്തുകളിൽ നിന്ന് ഒരു സൂറത്ത് ഓതുകയും അഞ്ച് റുകൂഉകളും, രണ്ട് സുജൂദും ചെയ്യുകയും ചെയ്തു. പിന്നീട് സൂര്യ ഗ്രഹണം പൂർണ്ണമായി ഒഴിവാകുന്നതു വരെ സാധാരണ പോലെ ഖിബിലയെ അഭിമുഖീകരിച്ചുകൊണ്ട് ദുആ ചെയ്യുന്ന അവസ്ഥയിൽ അവിടുന്ന് ഇരിക്കുകയും ചെയ്തു. (ദ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا أَنَا أَتَرَامَى بِأَسْهُمٍ لِي بِالْمَدِينَةِ إِذِ انْكَسَفَتِ الشَّمْسُ، فَجَمَعْتُ أَسْهُمِي وَقُلْتُ: لَأَنْظُرَنَّ مَا أَحْدَثَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي كُسُوفِ الشَّمْسِ، فَأَتَيْتُهُ مِمَّا يَلِي ظَهْرَهُ وَهُوَ فِي الْمَسْجِدِ، فَجَعَلَ يُسَبِّحُ وَيُكَبِّرُ وَيَدْعُو حَتَّى حُسِرَ عَنْهَا، قَالَ: ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ وَأَرْبَعَ سَجَدَاتٍ. (ن)', 'അബ്ദുറഹ്മാനുബ്നു സമുറ(റ): മദീനയിൽ വെച്ച് ഞാൻ എന്റെ അമ്പെയ്ത്ത് നടത്തി കൊണ്ടിരിക്കന്നതിനിടയിൽ സൂര്യ ഗ്രഹണം ഉണ്ടായി. ഞാൻ എന്റെ അമ്പുകൾ ശേഖരിക്കുകയും പറയുകയും (വിചാരിക്കുകയും) ചെയ്തു. ''സൂര്യ ഗ്രഹണത്തിൽ പുതുതായി റസൂൽ(സ) എന്താണ് ചെയ്യുന്നത് എന്ന് ഞാൻ ഇന്ന് നോക്കും. (ശ്രദ്ധിക്കും)'' അങ്ങനെ ഞാൻ നബി(സ)യുടെ അടുക്കൽ എത്തി, അവിടുത്തെ മുതുകിന് സമീപം നിന്നു. തിരുമേനി(സ) പള്ളിയിൽ ആയിരുന്നു. നബി(സ) സൂര്യനിൽ നിന്ന് ഗ്രഹണം ഒഴിവാകുന്നതുവരെ തസ്ബീഹും തക്ബീറും ചൊല്ലുവാനും പ്രാർത്ഥിക്കുവാനും തുടങ്ങി. നിവേദകൻ പറയുന്നു: ശേഷം, നബി(സ) നിന്ന് നാലു സുജൂദുകളോടെ രണ്ട് റകഅത്ത് നിസകരിക്കുകയും ചെയ്തു. (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ', 'അബ്ദുറഹ്മാനുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 645, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ حِينَ انْكَسَفَتِ الشَّمْسُ. فَقَالَ: "أَمَّا بَعْدُ". (ن)', 'സമുറ(റ): നബി(സ) സൂര്യ ഗ്രഹണ നിസ്കാരത്തിലെ ഖുതുബ നിർവ്വഹിക്കുമ്പോൾ ''അമ്മാ ബഅ്ദ്'' എന്നു പറഞ്ഞു തുടങ്ങി. (ന)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 646, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ ذَلِكَ فِي الْيَوْمِ الَّذِي مَاتَ فِيهِ إِبْرَاهِيمُ بْنُ رَسُولِ اللَّهِ صَلَّى اللَّهُ، عَلَيْهِ وَسَلَّمَ فَقَالَ النَّاسُ: إِنَّمَا كَسَفَتْ لِمَوْتِ إِبْرَاهِيمَ ابْنِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّى بِالنَّاسِ سِتَّ رَكَعَاتٍ فِي أَرْبَعِ سَجَدَاتٍ، كَبَّرَ، ثُمَّ قَرَأَ فَأَطَالَ الْقِرَاءَةَ، ثُمَّ رَكَعَ نَحْوًا مِمَّا قَامَ، ثُمَّ رَفَعَ رَأْسَهُ فَقَرَأَ دُونَ الْقِرَاءَةِ الْأُولَى، ثُمَّ رَكَعَ نَحْوًا مِمَّا قَامَ، ثُمَّ رَفَعَ رَأْسَهُ فَقَرَأَ الْقِرَاءَةَ الثَّالِثَةَ دُونَ الْقِرَاءَةِ الثَّانِيَةِ، ثُمَّ رَكَعَ نَحْوًا مِمَّا قَامَ، ثُمَّ رَفَعَ رَأْسَهُ فَانْحَدَرَ لِلسُّجُودِ، فَسَجَدَ سَجْدَتَيْنِ، ثُمَّ قَامَ فَرَكَعَ ثَلَاثَ رَكَعَاتٍ قَبْلَ أَنْ يَسْجُدَ، لَيْسَ فِيهَا رَكْعَةٌ إِلَّا الَّتِي قَبْلَهَا أَطْوَلُ مِنَ الَّتِي بَعْدَهَا إِلَّا أَنَّ رُكُوعَهُ نَحْوٌ مِنْ قِيَامِهِ قَالَ: ثُمَّ تَأَخَّرَ فِي صَلَاتِهِ، فَتَأَخَّرَتِ الصُّفُوفُ مَعَهُ، ثُمَّ تَقَدَّمَ فَقَامَ فِي مَقَامِهِ وَتَقَدَّمَتِ الصُّفُوفُ، فَقَضَى الصَّلَاةَ وَقَدْ طَلَعَتِ الشَّمْسُ، فَقَالَ: "يَا أَيُّهَا النَّاسُ، إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ عَزَّ وَجَلَّ، لَا يَنْكَسِفَانِ لِمَوْتِ بَشَرٍ، فَإِذَا رَأَيْتُمْ شَيْئًا مِنْ ذَلِكَ فَصَلُّوا حَتَّى تَنْجَلِيَ". (ق,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽലി(സ)ന്റെ കാലത്ത് സൂര്യഗ്രഹണം ഉണ്ടായി. അത് നബി(സ)യുടെ മകൻ ഇബ്രാഹിം മരണപ്പെട്ട ദിവസമായിരുന്നു. അപ്പോൾ ജനങ്ങൾ പറഞ്ഞു: "നബി(സ)യുടെ മകൻ ഇബ്രാഹിമിന്റെ മരണം കാരണമായി തന്നെയാണ് സൂര്യന് ഗ്രഹണം ബാധിച്ചത്." അപ്പോൾ നബി(സ) (നിസ്കാരത്തിനായി) നിന്ന് ആറു റുകൂഉം, നാലു സുജൂദുമായി ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കുകയും ചെയ്തു. നബി(സ) തക്ബീർ ചൊല്ലുകയും, ഖുർആൻ പാരായണം ചെയ്യുകയും പാരായണം ദീർഘിപ്പിക്കുകയും ചെയ്തു. പിന്നീട് ഏതാണ്ട് ആദ്യം നിന്ന സമയത്തോളം തന്നെ റുകൂഅ് ചെയ്തു, ശേഷം തല ഉയർത്തി. ആദ്യത്തെ തവണയെക്കാൾ കുറഞ്ഞ നിലയിൽ ഖുർആൻ ഓതുകയും ചെയ്തു. പിന്നെ അതേ സമയത്തോടടുത്ത നിലയിൽ റുകൂഅ് ചെയ്തു. പിന്നെ തല ഉയർത്തിയ നബി(സ) മൂന്നാം പ്രാവശ്യവും ഓതി, രണ്ടാം പ്രാവശ്യത്തെക്കാൾ കുറച്ച് ഓതി. പിന്നെ നിന്ന അത്രതന്നെ സമയത്തോളം നബി(സ) റുകൂഅ് ചെയ്തു. ശേഷം തല ഉയർത്തി സുജൂദിലേക്ക് പോകുകയും, രണ്ട് സുജൂദ് ചെയ്യുകയും ചെയ്തു. പിന്നെ നിൽക്കുകയും സുജൂദ് ചെയ്യുന്നതിന് മുമ്പ് മൂന്ന് റുകൂഅ് ചെയ്യുകയും ചെയ്തു. ആ നിസ്കാരത്തിലെ ആദ്യത്തെ റക്അത്ത് അതിന്റെ ശേഷം വരുന്ന റക്അത്തിനെക്കാൾ വളരെ ദൈർഘ്യം ഉള്ളതായിരുന്നു. എന്നാൽ നബി(സ)യുടെ റുകൂഅ് ഏതാണ്ട് അവിടുത്തെ നിർത്തത്തോട് ഒത്ത നിലയിലുള്ള റുകൂഅ് ആയിരുന്നു. (ഒന്നാം റകഅത്തിലെ റുകൂഉകളുടെ ദൈർഘ്യം. ആ റകഅത്തിന്റെ ദൈർഘ്യത്തോട് അടുത്ത നിലയിൽ ആയിരുന്നതു പോലെ. രണ്ടാം റകഅത്തിലെ റുകൂഉകൾ ആ റകഅത്തിന്റെ ദൈർഘ്യത്തോട് അടുത്ത നിലയിലും ആയിരുന്നു.) നിവേദകൻ പറയുന്നു: പിന്നെ നിസ്കാരത്തിൽ തിരുമേനി(സ) പിറകോട്ട് മാറി. അപ്പോൾ അവിടത്തോടൊപ്പം പിന്നിലുള്ളവരും പിറകോട്ട് മാറി. പിന്നെ നബി(സ) മുന്നോട്ട് കയറുകയും ചെയ്തു. നബി(സ) നേരത്തെ നിന്ന സ്ഥലത്ത് നിന്നപ്പോൾ സ്വഫ്ഫുകളും മുന്നോട്ട് നീങ്ങി. അങ്ങനെ നബി(സ) നിസ്കാരം പൂർത്തിയാക്കി. സൂര്യൻ ഉദിച്ചു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "ഏ ജനങ്ങളെ, നിശ്ചയം, സൂര്യനും ചന്ദ്രനും അല്ലാഹുവിന്റെ ദൃഷ്ടാന്തങ്ങളിൽപെട്ട രണ്ട് ദൃഷ്ടാന്തങ്ങളാണ്. മനുഷ്യന്റെ മരണം കാരണമായി അവ രണ്ടിനും ഗ്രഹണം ബാധിക്കുകയില്ല. ആയതിനാൽ അതിൽ നിന്ന് അൽപത്തെ നിങ്ങൾ കണ്ടാൽ (കുറഞ്ഞ തോതിലെങ്കിലും നിങ്ങൾ ഗ്രഹണം കണ്ടാൽ) സൂര്യൻ പൂർണ്ണമായി പ്രകാശിക്കുന്നതു വരെ നിങ്ങൾ നിസ്കരിക്കുവിൻ!" (ബു,മു,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 646, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي يَوْمٍ شَدِيدِ الْحَرِّ، فَصَلَّى بِأَصْحَابِهِ، فَأَطَالَ الْقِيَامَ حَتَّى جَعَلُوا يَخِرُّونَ، ثُمَّ رَكَعَ فَأَطَالَ، ثُمَّ رَفَعَ فَأَطَالَ، ثُمَّ رَكَعَ فَأَطَالَ، ثُمَّ رَفَعَ فَأَطَالَ، ثُمَّ سَجَدَ سَجْدَتَيْنِ، ثُمَّ قَامَ فَصَنَعَ نَحْوًا مِنْ ذَلِكَ، فَكَانَتْ أَرْبَعَ رَكَعَاتٍ وَأَرْبَعَ سَجَدَاتٍ. (م,د,ن)', 'ജാബിർ(റ): റസൂലി(സ)ന്റെ കാലത്ത് ചൂട് കഠിനമായ ഒരു ദിവസം സൂര്യ ഗ്രഹണം ഉണ്ടായി. അപ്പോൾ നബി(സ) തന്റെ അനുചരരോടൊപ്പം നിസ്കരിച്ചു. അവർ (അനുചരർ കുഴഞ്ഞ്) വീഴാൻ തുടങ്ങുന്നതുവരെ നബി(സ) നിസ്കാരത്തിലെ നിർത്തം ദീർഘിപ്പിച്ചു. പിന്നെ അവിടുന്ന് റുകൂഅ് ചെയ്യുകയും അതിനെ ദീർഘിപ്പിക്കുകയും ചെയ്തു. പിന്നെ ഉയരുകയും, (നിർത്തത്തെ) ദീർഘിപ്പിക്കുകയും ചെയ്തു. പിന്നീട് റുകൂഅ് ചെയ്യുകയും റുകൂഇനെ ദീർഘിപ്പിക്കുകയും ചെയ്തു. പിന്നെ ഉയർന്നു. (നിർത്തം) ദീർഘിപ്പിച്ചു. പിന്നെ രണ്ട് സുജൂദ് ചെയ്തു. ശേഷം നിൽക്കുകയും ആദ്യത്തെ റക്അത്തിൽ ചെയ്തതു പോലെ തന്നെ നബി(സ) അടുത്ത റക്അത്തിലും ചെയ്യുകയും ചെയ്തു. അങ്ങനെ നാലു റുകൂഉം, നാലു സുജൂദുമായി നിസ്കാരം പൂർത്തിയാക്കി. (മു,ദ,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 647, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي كُسُوفٍ – فِي صُفَّةِ زَمْزَمَ – أَرْبَعَ رَكَعَاتٍ فِي أَرْبَعِ سَجَدَاتٍ. (ن)', 'ആഇശ(റ): ഗ്രഹണ വേളയിൽ - സംസമിന്റെ വിശാലമായ സ്ഥലത്ത് - നാലു റുകൂഉം നാലു സുജൂദുമായി നബി(സ) നിസ്കരിച്ചു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 647, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُ قَالَ: انْكَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَكَدْ يَرْكَعُ ثُمَّ رَكَعَ، فَلَمْ يَكَدْ يَرْفَعُ ثُمَّ رَفَعَ، فَلَمْ يَكَدْ يَسْجُدُ ثُمَّ سَجَدَ، فَلَمْ يَكَدْ يَرْفَعُ ثُمَّ رَفَعَ، فَلَمْ يَكَدْ يَسْجُدُ ثُمَّ سَجَدَ، فَلَمْ يَكَدْ يَرْفَعُ ثُمَّ رَفَعَ، وَفَعَلَ فِي الرَّكْعَةِ الْأُخْرَى مِثْلَ ذَلِكَ، ثُمَّ نَفَخَ فِي آخِرِ سُجُودِهِ، فَقَالَ: "أُفْ أُفْ" ثُمَّ قَالَ: "رَبِّ، أَلَمْ تَعِدْنِي أَنْ لَا تُعَذِّبَهُمْ وَأَنَا فِيهِمْ؟ أَلَمْ تَعِدْنِي أَنْ لَا تُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ". فَفَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ صَلَاتِهِ وَقَدْ أَمْحَصَتِ الشَّمْسُ. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂലി(സ)ന്റെ കാലത്ത് സൂര്യ ഗ്രഹണമുണ്ടായപ്പോൾ അവിടുന്ന് നിസ്കരിക്കാൻ നിന്നു. റുകൂഅ് ചെയ്യുവാൻ നബി(സ) അടുത്തില്ല (അതായത് നിർത്തം ദീർഘമാക്കി). പിന്നെ റുകൂഅ് ചെയ്തു. (റുകൂഇൽ നിന്ന്) ഉയരുവാൻ അടുത്തില്ല (ദീർഘമായി റുഖൂഅ് ചെയ്തു). പിന്നെ ഉയർന്നു; സുജൂദ് ചെയ്യുവാൻ അടുത്തില്ല. പിന്നെ സുജൂദ് ചെയ്തു. ഉയരുവാൻ അടുത്തില്ല (അതായത് സുജൂദ് ദീർഘിപ്പിച്ചു). പിന്നെ ഉയർന്നു. പിന്നെ സുജൂദ് ചെയ്യാൻ അടുത്തില്ല, ശേഷം സുജൂദ് ചെ്യതു. പിന്നെ ഉയരുവാൻ അടുത്തില്ല, ശേഷം ഉയർന്നു. അടുത്ത റക്അത്തിലും നബി(സ) ഇപ്രകാരം തന്നെ ചെയ്തു. പിന്നെ അവസാനത്തെ സുജൂദിൽ ''ഉഫ്, ഉഫ്'' എന്നു പറഞ്ഞ് നബി(സ) ഊതി. തുടർന്ന് അവിടുന്ന് പറഞ്ഞു: "എന്റെ നാഥാ, ഞാൻ അവർക്കിടയിൽ ഉണ്ടായിരിക്കെ നീ അവരെ ശിക്ഷിക്കുകയില്ല എന്ന് നീ എന്നോട് കരാർ ചെയ്തിട്ടില്ലയോ? അവർ (തെറ്റുകളിൽ നിന്ന്) പശ്ചാത്തപിച്ചു കൊണ്ടിരിക്കെ അവരെ ശിക്ഷിക്കുകയില്ലെന്ന് നീ എന്നോട് കരാർ ചെയ്തിട്ടില്ലയോ?" തുടർന്ന് നബി(സ) നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചു. സൂര്യൻ ഗ്രഹണ മുക്തമാകുകയും ചെയ്തിരുന്നു. (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 647, 648, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ صَلَّى فِي كُسُوفِ الشَّمْسِ، فَقَرَأَ ثُمَّ رَكَعَ، ثُمَّ قَرَأَ ثُمَّ رَكَعَ، ثُمَّ قَرَأَ ثُمَّ رَكَعَ، ثُمَّ سَجَدَ، وَالْأُخْرَى مِثْلُهَا. (م,د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): സൂര്യ ഗ്രഹണ വേളയിൽ നബി(സ) നിസ്കരിച്ചപ്പോൾ അവിടുന്ന് ഖുർആൻ പാരായണം ചെയ്തു, പിന്നീട് റുകൂഅ് ചെയ്തു, ശേഷം ഖുർആൻ പാരായണം ചെയ്തു, പിന്നീട് റുകൂഅ് ചെയ്തു, പിന്നീട് ഖുർആൻ പാരായണം ചെയ്തു, പിന്നെ റുകൂഅ് ചെയ്തു. വീണ്ടും ഖുർആൻ പാരായണം ചെയ്തു, ശേഷം റുകൂഅ് ചെയ്തു, പിന്നെ സുജൂദ് ചെയ്തു, അടുത്ത റക്അത്തും അതുപോലെതന്നെ നിർവ്വഹിച്ചു. (മു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 648, 648, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُ قَالَ: خَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ فَنُودِيَ: الصَّلَاةُ جَامِعَةً، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّاسِ رَكْعَتَيْنِ وَسَجْدَةً، ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ وَسَجْدَةً، قَالَتْ عَائِشَةُ: مَا رَكَعْتُ رُكُوعًا قَطُّ، وَلَا سَجَدْتُ سُجُودًا قَطُّ، كَانَ أَطْوَلَ مِنْهُ. (د)', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ): റസൂലി(സ)ന്റെ കാലത്ത് സൂര്യന് ഗ്രഹണം ബാധിച്ചപ്പോൾ. അവിടുന്ന് (വിളിച്ചറിയിക്കുവാൻ) കൽപിക്കുകയും അതനുസരിച്ച് ''അസ്സലാത്തു ജാമിഅ'' എന്നു വിളിച്ചറിയിക്കപ്പെടുകയും ചെയ്തു. ജനങ്ങൾക്ക് ഇമാമായി നബി(സ) നിസ്കരിച്ചു. രണ്ട് റുകൂഉം, ഒരു സുജൂദും നിർവ്വഹിച്ച ശേഷം നബി(സ) നിന്നു. ശേഷം രണ്ട് റുകൂഉം, ഒരു സുജൂദുമായി നിസ്കരിച്ചു. ആഇശ(റ) പറയുന്നു. ഇതിനേക്കാൾ നീണ്ട റുകൂഉം സുജൂദും ഒരിക്കലും ഞാൻ ചെയ്തിട്ടില്ല. (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 648, 648, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَخْبَرَتْهُ أَنَّهُ لَمَّا كَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، وَأَمَرَ فَنُودِيَ: أَنَّ الصَّلَاةَ جَامِعَةً، فَقَامَ فَأَطَالَ الْقِيَامَ فِي صَلَاتِهِ، قَالَتْ عَائِشَةُ: فَحَسَبْتُ قَرَأَ سُورَةَ الْبَقَرَةِ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ قَالَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ". ثُمَّ قَامَ مِثْلَ مَا قَامَ، وَلَمْ يَسْجُدْ، ثُمَّ رَكَعَ فَسَجَدَ، ثُمَّ قَامَ فَصَنَعَ مِثْلَ مَا صَنَعَ رَكْعَتَيْنِ وَسَجْدَةً، ثُمَّ جَلَسَ، وَجُلِّيَ عَنِ الشَّمْسِ. (خ,ن)', 'ആഇശ(റ): നബി(സ)യുടെ കാലത്ത് സൂര്യ ഗ്രഹണം ബാധിച്ചപ്പോൾ അവിടുന്ന് വുദു ചെയ്യുകയും, (വിളിച്ച് പറയാൻ) ആജ്ഞാപിച്ചതനുസരിച്ച് "നിസ്കാരം കൂട്ടമായി നിർവ്വഹിക്കുന്നു" എന്ന് വിളിച്ചറിയിക്കപ്പെടുകയും ചെയ്തു. നബി(സ) നിന്ന് അവിടുത്തെ നിസ്കാരത്തിൽ നിർത്തം ദീർഘിപ്പിക്കുകയും ചെയ്തു. ആഇശ(റ) പറയുന്നു: സൂറത്തുൽ ബഖറയാണ് ഓതിയതെന്ന് ഞാൻ കരുതുന്നു. പിന്നീട് റുകൂഅ് ചെയ്യുകയും റുകൂഇനെ ദീർഘിപ്പിക്കുകയും ചെയ്തു. പിന്നെ ''സമിഅല്ലാഹു ലിമൻ ഹമിദ'' എന്ന് പറയുകയും സുജൂദ് ചെയ്യാത്ത അവസ്ഥയിൽ നേരത്തെ നിന്നതു പോലെ വീണ്ടും നിൽക്കുകയും ചെയ്തു. ശേഷം റുകൂഅ് ചെയ്യുകയും പിന്നീട് സുജൂദ് ചെയ്യുകയും ചെയ്തു. ശേഷം എഴുന്നേറ്റ് മുമ്പത്തേതു പോലെതന്നെ രണ്ട് റുകൂഉം ഒരു സുജൂദും ചെയ്യുകയും പിന്നെ (തശഹ്ഹുദിന്) ഇരിക്കുകയും ചെയ്തു. സൂര്യനിൽ നിന്ന് ഗ്രഹണം ഒഴിവാകുകയും ചെയ്തു. (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 648, 648, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَسَفَتِ الشَّمْسُ، فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا فَنَادَى: أَنِ الصَّلَاةَ جَامِعَةً، فَاجْتَمَعَ النَّاسُ، فَصَلَّى بِهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَكَبَّرَ، ثُمَّ قَرَأَ قِرَاءَةً طَوِيلَةً، ثُمَّ كَبَّرَ فَرَكَعَ رُكُوعًا طَوِيلًا مِثْلَ قِيَامِهِ أَوْ أَطْوَلَ، ثُمَّ رَفَعَ رَأْسَهُ، وَقَالَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ". ثُمَّ قَرَأَ قِرَاءَةً طَوِيلَةً هِيَ أَدْنَى مِنَ الْقِرَاءَةِ الْأُولَى، ثُمَّ كَبَّرَ فَرَكَعَ رُكُوعًا طَوِيلًا هُوَ أَدْنَى مِنَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ رَفَعَ رَأْسَهُ، فَقَالَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ". ثُمَّ كَبَّرَ فَسَجَدَ سُجُودًا طَوِيلًا مِثْلَ رُكُوعِهِ أَوْ أَطْوَلَ، ثُمَّ كَبَّرَ فَرَفَعَ رَأْسَهُ، ثُمَّ كَبَّرَ فَسَجَدَ، ثُمَّ كَبَّرَ فَقَامَ فَقَرَأَ قِرَاءَةً طَوِيلَةً هِيَ أَدْنَى مِنَ الْأُولَى، ثُمَّ كَبَّرَ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلًا هُوَ أَدْنَى مِنَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ رَفَعَ رَأْسَهُ فَقَالَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ". ثُمَّ قَرَأَ قِرَاءَةً طَوِيلَةً، وَهِيَ أَدْنَى مِنَ الْقِرَاءَةِ الْأُولَى فِي الْقِيَامِ الثَّانِي، ثُمَّ كَبَّرَ فَرَكَعَ رُكُوعًا طَوِيلًا دُونَ الرُّكُوعِ الْأَوَّلِ، ثُمَّ كَبَّرَ فَرَفَعَ رَأْسَهُ فَقَالَ: "سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ". ثُمَّ كَبَّرَ فَسَجَدَ أَدْنَى مِنْ سُجُودِهِ الْأَوَّلِ، ثُمَّ تَشَهَّدَ، ثُمَّ سَلَّمَ، فَقَامَ فِيهِمْ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، وَلَكِنَّهُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ، فَأَيُّهُمَا خُسِفَ بِهِ، أَوْ بِأَحَدِهِمَا، فَافْزَعُوا إِلَى اللَّهِ عَزَّ وَجَلَّ بِذِكْرِ الصَّلَاةِ". (ن)', 'ആഇശ(റ): സൂര്യന് ഗ്രഹണം ബാധിച്ചു. അപ്പോൾ റസൂൽ(സ) ഒരാളോട് ആജ്ഞാപിച്ചതനുസരിച്ച് ''നിസ്കാരം കൂട്ടമായി നിർവ്വഹിക്കുന്നു'' എന്ന് അദ്ദേഹം വിളിച്ചു പറയുകയും ജനങ്ങൾ വന്നു ചേരുകയും റസൂൽ(സ) അവർക്ക് ഇമാമായി നിസ്കരിക്കുകയും ചെയ്തു. അവിടുന്ന് തക്ബീർ ചൊല്ലുകയും ദീർഘമായി ഖുർആൻ പാരായണം നടത്തുകയും ചെയ്തു. പിന്നെ തക്ബീർ ചൊല്ലി, നബി(സ)യുടെ നിർത്തത്തെ പോലെയോ അതിനേക്കാൾ ദീർഘമായ നിലയിലോ നീണ്ട റുകൂഉം ചെയ്തു. പിന്നീട് തല ഉയർത്തുകയും ''സമിഅല്ലാഹു ലിമൻ ഹമിദ'' എന്നു പറയുകയും ആദ്യത്തെ പാരായണത്തേക്കാൾ ദൈർഘ്യം കുറഞ്ഞ പാരായണം നടത്തുകയും, ശേഷം തക്ബീർ ചൊല്ലി ആദ്യത്തെ റുകൂഇനേക്കാൾ കുറഞ്ഞ ദൈർഘ്യമുള്ള റുകൂഅ് ചെയ്യുകയും പിന്നീട് തല ഉയർത്തി ''സമിഅല്ലാഹു ലിമൻ ഹമിദ'' എന്നു പറയുകയും ചെയ്തു. പിന്നെ തക്ബീർ ചൊല്ലി നേരത്തെ ചെയ്ത റുകൂഇനെ പോലെയോ അതിനേക്കാൾ ദീർഘമായ നിലയിലോ നബി(സ) നീണ്ട സുജൂദ് ചെയ്തു. പിന്നെ തക്ബീർ ചൊല്ലി തല ഉയർത്തുകയും വീണ്ടും തക്ബീർ ചൊല്ലി സുജൂദ് ചെയ്യുകയും ചെയ്തു. പിന്നീട് നബി(സ) തക്ബീർ ചൊല്ലി നിൽക്കുകയും നീണ്ട ഖുർആൻ പാരായണം നടത്തുകയും ചെയ്തു. അത് ആദ്യത്തെ പാരായണത്തേക്കാൾ ദൈർഘ്യം കുറഞ്ഞതായിരുന്നു. പിന്നെ തക്ബീർ ചൊല്ലി റുകൂഉം ചെയ്തു. അത് ആദ്യത്തെ റുകൂഇനേക്കാൾ (ദൈർഘ്യം) കുറഞ്ഞതായിരുന്നു. പിന്നെ നബി(സ) തല ഉയർത്തി ''സമിഅല്ലഹു ലിമൻ ഹമിദ'' പറഞ്ഞു. ശേഷം നബി(സ) ദീർഘമായി ഖുർആൻ പാരായണം ചെയ്തു. അത് രണ്ടാമത്തെ നിർത്തത്തിലെ ആദ്യത്തെ പാരായണത്തേക്കാൾ ദൈർഘ്യം കുറഞ്ഞ നിലയിലായിരുന്നു. ശേഷം തക്ബീർ ചൊല്ലി ആദ്യത്തെ റുകൂഇനേക്കാൾ ചെറിയ റുകൂഅ് ചെയ്തു ശേഷം തക്ബീർ ചൊല്ലി ''സമിഅല്ലാഹു ലിമൻ ഹമിദ'' എന്നു പറയുകയും ചെയ്തു. പിന്നീട് നബി(സ) തക്ബീർ ചൊല്ലി. അവിടുത്തെ ആദ്യത്തെ സുജൂദിനെക്കാൾ (ദൈർഘ്യം) കുറഞ്ഞ സുജൂദ് ചെയ്യുകയും പിന്നീട് അത്തഹിയ്യാത്ത് ഓതുകയും ശേഷം സലാം വീട്ടുകയും ചെയ്തു. ശേഷം അവർക്കിടയിൽ നിന്ന് അവിടുന്ന് അല്ലാഹുവിനെ വാഴ്ത്തുകയും പുകഴ്ത്തുകയും ചെയ്ത ശേഷം പറഞ്ഞു: "തീർച്ചയായും സൂര്യന്നും ചന്ദ്രന്നും ആരുടെയും മരണ കാരണമായോ, ജനന കാരണമായോ ഗ്രഹണം സംഭവിക്കുകയില്ല, അവ രണ്ടും അല്ലാഹുവിന്റെ ദൃഷ്ടാന്തങ്ങളിൽപെട്ട രണ്ട് ദൃഷ്ടാന്തങ്ങളാണ്. അവ രണ്ടിലൊന്നിന് ഗ്രഹണം ബാധിച്ചാൽ നിസ്കാരത്തെ സ്മരിച്ചുകൊണ്ട് ഭയപ്പെട്ടവരായ നിലയിൽ നിങ്ങൾ അല്ലാഹുവിലേക്ക് ധൃതിയിൽ എത്തുവിൻ." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 648, 649, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنِ النَّضْرِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتْ ظُلْمَةٌ عَلَى عَهْدِ أَنَسِ بْنِ مَالِكٍ، قَالَ: فَأَتَيْتُ أَنَسًا، فَقُلْتُ: يَا أَبَا حَمْزَةَ، هَلْ كَانَ يُصِيبُكُمْ مِثْلُ هَذَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: مَعَاذَ اللَّهِ، إِنْ كَانَتِ الرِّيحُ لَتَشْتَدُّ، فَنُبَادِرُ الْمَسْجِدَ مَخَافَةَ الْقِيَامَةِ. (د)', 'നള്റ്(റ): അനസുബ്നു മാലികി(റ)ന്റെ കാലത്ത് ഇരുട്ട് ബാധിച്ചപ്പോൾ ഞാൻ അനസി(റ)ന്റെ അടുക്കൽ വന്ന് പറഞ്ഞു: ഓ അബൂഹംസാ, റസൂലി(സ)ന്റെ കാലത്ത് ഇപ്രകാരം (പകലിൽ ഇരുൾ) നിങ്ങൾക്ക് സംഭവിക്കുമായിരുന്നോ? അനസ്(റ) പറഞ്ഞു: ''അല്ലാഹുവേ രക്ഷ, കാറ്റ് ശക്തിയായി അടിച്ചു വീശുന്ന സംഭവം ഉണ്ടായാൽ പോലും ലോകാവസാനമാണോ എന്ന ഭയത്തോടെ അതിവേഗം ഞങ്ങൾ പള്ളിയിലെത്തുമായിരുന്നു. (ദ)', 'النَّضْرِ', 'നള്റ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عِكْرِمَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قِيلَ لِابْنِ عَبَّاسٍ: مَاتَتْ فُلَانَةُ، بَعْضُ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخَرَّ سَاجِدًا، فَقِيلَ لَهُ: أَتَسْجُدُ هَذِهِ السَّاعَةَ؟ فَقَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا رَأَيْتُمْ آيَةً فَاسْجُدُوا". وَأَيُّ آيَةٍ أَعْظَمُ مِنْ ذَهَابِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ (ت,ن)', 'ഇക്രിമ(റ): ഇബ്നുഅബ്ബാസി(റ)നോട് പറയപ്പെട്ടു: റസൂലി(സ)ന്റെ ഭാര്യമാരിൽ നിന്ന് ഇന്ന സ്ത്രീ വഫാതായിരിക്കുന്നു. അതു കേട്ട ഉടനെ അദ്ദേഹം സൂജൂദിൽ വീണു. അപ്പോൾ അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: ഈ സമയത്ത് നിങ്ങൾ സുജൂദ് ചെയ്യുകയാണോ? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഒരു ദൃഷ്ടാന്തം (ആപത്ത്) കണ്ടാൽ സുജൂദ് ചെയ്യുവിൻ!" റസൂലി(സ)ന്റെ ഭാര്യമാർ പോകുന്നതിനേക്കാൾ വലിയ ദൃഷ്ടാന്തം (ആപത്ത്) എന്താണുള്ളത്? (തു,ന)', 'عِكْرِمَةَ', 'ഇക്രിമ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: خَسَفَتِ الشَّمْسُ، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَزِعًا، يَخْشَى أَنْ تَكُونَ السَّاعَةُ، فَأَتَى الْمَسْجِدَ، فَصَلَّى بِأَطْوَلِ قِيَامٍ وَرُكُوعٍ وَسُجُودٍ رَأَيْتُهُ قَطُّ يَفْعَلُهُ. وَقَالَ: "هَذِهِ الْآيَاتُ الَّتِي يُرْسِلُ اللَّهُ، لَا تَكُونُ لِمَوْتِ أَحَدٍ، وَلَا لِحَيَاتِهِ، وَلَكِنْ يُخَوِّفُ اللَّهُ بِهِ عِبَادَهُ، فَإِذَا رَأَيْتُمْ شَيْئًا مِنْ ذَلِكَ، فَافْزَعُوا إِلَى ذِكْرِهِ وَدُعَائِهِ وَاسْتِغْفَارِهِ". (خ,ن)', 'അബൂമൂസാ(റ): സൂര്യ ഗ്രഹണം ഉണ്ടായപ്പോൾ ലോകാവസാനമാണോ എന്ന് ഭയപ്പെട്ട് നബി(സ) (എഴുന്നേറ്റ്) നിന്നു. അവിടുന്ന് പള്ളിയിലേക്കുവന്നു, നിസ്കരിക്കുവാൻ നിന്നു. ദീർഘമായ നിർത്തത്തോടും, റുകൂഓടും, സുജൂദോടും കൂടിയുള്ള നിസ്കാരം നിർവ്വഹിച്ചു. ഒരിക്കലും നബി(സ) ഇപ്രകാരം നിസ്കരിക്കുന്നതായി ഞാൻ കണ്ടിട്ടില്ല. ശേഷം നബി(സ) പറഞ്ഞു; "നിശ്ചയം, ഇതെല്ലാം അല്ലാഹു അയക്കുന്ന ദൃഷ്ടാന്തങ്ങളാണ്. ആരുടെയും മരണവും ജനനവും മുഖേന ഉണ്ടാകുന്നവയല്ല. ഇവയെ അല്ലാഹു തന്റെ അടിമകളെ ഭയപ്പെടുത്തുന്നതിനായി അയക്കുന്നു. ഇവയിൽ നിന്ന് എന്തെങ്കിലും നിങ്ങൾ കണ്ടാൽ അല്ലാഹുവിന്റെ സ്മരണയിലേക്കും, പ്രാർത്ഥനയിലേക്കും, പാപ മോചനത്തിലേക്കും ഭയത്തോടെ നിങ്ങൾ ധൃതിപ്പെടുവിൻ!" (ബു,ന)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=24 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
